		public void UpdatePartyEggHatchingCount(int step) {
            PlayerWork.WalkCount += step;
            if (CalendarEnc.CalEnc_GetHaching() + 255 <= PlayerWork.WalkCount)
            {
                PlayerWork.WalkCount = 0f;
                int value = GetPartyEggHatchingValue(1);
                var party = PlayerWork.playerParty;
                int memberCount = (int)party.GetMemberCount();
                for (int i = 0; i < memberCount; i++)
                {
                    var pokemonParam = party.GetMemberPointer((uint)i);
                    if (pokemonParam.IsEgg(EggCheckType.ONLY_LEGAL_EGG))
                    {
                        int count = Mathf.Max((int)pokemonParam.GetOriginalFriendship() - value, 0);
                        pokemonParam.SetOriginalFriendship((uint)count);
                    }
                }
            }
        }
		private int GetPartyEggHatchingValue(int step) {
            var party = PlayerWork.playerParty;
            int memberCount = (int)party.GetMemberCount();
            for (int i = 0; i < memberCount; i++)
            {
                var pokemonParam = party.GetMemberPointer((uint)i);
                if (pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                    continue;

                TokuseiNo tokusei = pokemonParam.GetTokuseiNo();
                if (tokusei == TokuseiNo.MAGUMANOYOROI || tokusei == TokuseiNo.ZYOUKIKIKAN || tokusei == TokuseiNo.HONOONOKARADA)
                    return step * 2;
            }

            return step;
        }
		private bool CheckPartyEggHatching() {
            var party = PlayerWork.playerParty;
            int memberCount = (int)party.GetMemberCount();
            for (int i = 0; i < memberCount; i++)
            {
                var pokemonParam = party.GetMemberPointer((uint)i);
                if (pokemonParam.IsEgg(EggCheckType.ONLY_LEGAL_EGG) && pokemonParam.GetOriginalFriendship() == 0)
                    return EntityManager.activeFieldPlayer.currentSequence == FieldObjectEntity.SequenceID.Active;
            }

            return false;
        }
		private int CheckPartyEggHatchingCount() {
            int count = 0;
            var party = PlayerWork.playerParty;
            int memberCount = (int)party.GetMemberCount();
            for (int i = 0; i < memberCount; i++)
            {
                var pokemonParam = party.GetMemberPointer((uint)i);
                if (pokemonParam.IsEgg(EggCheckType.ONLY_LEGAL_EGG) && pokemonParam.GetOriginalFriendship() == 0)
                    count++;
            }

            return count;
        }
