		public bool CheckPosEvent(out global::UnityEngine.Vector3 outWorldPos, global::FieldPlayerEntity player) {
            outWorldPos = Vector3.zero;
            if (_eventListIndex >= 0 || _battleReturnData.EventListIndex >= 0)
                return false;

            // IsPlayingUgEnterOrExit is inlined here in the binary.
            if (IsPlayingUgEnterOrExit())
                return false;

            if (_posEventLabelReserve != null)
                return false;

            if (_eventEndPosition == FieldObjectEntity.PositionToGrid(player.worldPosition + player.moveVector))
                return false;

            _eventEndPosition = Vector2Int.zero;
            var entityParam = FieldGridCollision.CheckGridEventMoveEntity(out outWorldPos, player);
            if (entityParam == null)
                return false;

            PlayerInputActive(false, false);
            Vector2Int nowGrid = FieldObjectEntity.PositionToGrid(outWorldPos);
            Vector2Int oldGrid = player.oldGridPosition;
            _heroMoveGridCenterFrontDir = SetupHeroMoveGridCenterFrontDir(in entityParam.StopGridArea, in nowGrid, in oldGrid);
            _posEventLabelReserve = entityParam.ContactLabel;
            return true;
        }
		public global::Dpr.EvScript.EvDataManager.EntityParam GetPosEventFromGrid(global::UnityEngine.Vector2Int gridPos) {
            if (_entityParamList == null)
                return null;

            for (int i = 0; i < _entityParamList.Length; i++)
            {
                var entityParam = _entityParamList[i];
                if (entityParam == null)
                    continue;

                var rect = new Rect(entityParam.StopGridArea.x, entityParam.StopGridArea.y, entityParam.StopGridArea.width + 1, entityParam.StopGridArea.height + 1);
                if (!rect.Contains((Vector2)gridPos))
                    continue;

                bool isVisible = true;
                if (entityParam.VanishFlagIndex > -1 && entityParam.VanishFlagIndex != (int)EvWork.FLAG_INDEX.FLAG_END_SAVE_SIZE)
                    isVisible = !FlagWork.GetFlag((EvWork.FLAG_INDEX)entityParam.VanishFlagIndex);

                if (entityParam.WorkIndex != EvWork.WORK_INDEX.SCWK_WK_SAVE_SIZE)
                    isVisible &= FlagWork.GetWork(entityParam.WorkIndex) == entityParam.WorkValue;

                if (isVisible && !string.IsNullOrEmpty(entityParam.ContactLabel))
                    return entityParam;
            }

            return null;
        }
		private bool IsPosEventOverWarp(ref global::UnityEngine.Vector3 pos) {
            var gridPos = new Vector2(Mathf.Abs(pos.x), Mathf.Abs(pos.z));
            for (int i = 0; i < _entityParamList.Length; i++)
            {
                var entityParam = _entityParamList[i];
                if (entityParam == null)
                    continue;

                var rect = new Rect(entityParam.StopGridArea.x, entityParam.StopGridArea.y, entityParam.StopGridArea.width + 1, entityParam.StopGridArea.height + 1);
                if (!rect.Contains(gridPos))
                    continue;

                if (entityParam.VanishFlagIndex > -1 && entityParam.VanishFlagIndex != (int)EvWork.FLAG_INDEX.FLAG_END_SAVE_SIZE && FlagWork.GetFlag((EvWork.FLAG_INDEX)entityParam.VanishFlagIndex))
                    return false;

                if (entityParam.WorkIndex != EvWork.WORK_INDEX.SCWK_WK_SAVE_SIZE && FlagWork.GetWork(entityParam.WorkIndex) != entityParam.WorkValue)
                    return false;

                return true;
            }

            return false;
        }
