                _voice_datas[freeIndex].playEventId = 0;
            }
            else
            {
                _voice_datas[freeIndex].playEventId = _voice_datas[freeIndex].AudioInstance.playEventId;
                _voice_datas[freeIndex].AudioInstance.Play(instance =>
                {
                    for (int i = 0; i < _voice_datas.Length; i++)
                    {
                        if (_voice_datas[i].AudioInstance != null && _voice_datas[i].playEventId == instance.playEventId)
                        {
                            _voice_datas[i].playEventId = 0;
