		private void BattleTrainer(global::Dpr.Trainer.TrainerID enemy1, global::Dpr.Trainer.TrainerID enemy2 = (global::Dpr.Trainer.TrainerID)(0), global::Dpr.Trainer.TrainerID partner = (global::Dpr.Trainer.TrainerID)(0)) {
            bool isFindEnemy1 = false;
            bool isFindEnemy2 = enemy2 == TrainerID.NONE;
            foreach (var moveCode in FieldObjectMoveCodes)
            {
                if (!isFindEnemy1 && moveCode.TrainerID == enemy1)
                {
                    moveCode.MoveCode = 0;
                    isFindEnemy1 = true;
                }

                if (!isFindEnemy2 && moveCode.TrainerID == enemy2)
                {
                    moveCode.MoveCode = 0;
                    isFindEnemy2 = true;
                }

                if (isFindEnemy1 && isFindEnemy2)
                    break;
            }

            TrainerWork.ReSetBattleSaercher(enemy1);
            TrainerWork.ReSetBattleSaercher(enemy2);
            TrainerID trainerID1 = TrainerWork.RematchTrainerID(enemy1);
            TrainerID trainerID2 = TrainerWork.RematchTrainerID(enemy2);
            Btl_TrainerType1 = TrainerSystem.GetTrainerData(trainerID1).TypeID;
            Btl_TrainerType2 = trainerID2 != TrainerID.NONE ? TrainerSystem.GetTrainerData(trainerID2).TypeID : TrainerType.INVALID;

            var battleSetupParam = PlayerWork.battleSetupParam;
            var attributeEx = GameManager.GetAttributeEx(EntityManager.activeFieldPlayer.gridPosition, EntityManager.activeFieldPlayer.Height, false);
            GameManager.GetAttribute(EntityManager.activeFieldPlayer.gridPosition, out int code, out int stop, false);
            bool isWater = AttributeID.MATR_IsWater(GameManager.GetAttributeTable(code).Code);
            var arenaID = GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[isWater ? 1 : 0];
            var weatherType = FieldManager.Instance.GetBatleWeather();

            BtlRule rule = BtlRule.BTL_RULE_SINGLE;
            if (trainerID2 != TrainerID.NONE)
            {
                if (partner == TrainerID.NONE)
                    partner = FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_PAIR) ? (TrainerID)FlagWork.GetWork(EvWork.WORK_INDEX.SYS_WORK_PAIR_TRAINER_ID) : TrainerID.NONE;

                rule = BtlRule.BTL_RULE_DOUBLE;
            }

            Dpr.EncountTools.SetupBattleTrainer(battleSetupParam, arenaID, attributeEx.AttributeEx, weatherType, rule, trainerID1, trainerID2, partner);
            FieldManager.Instance.EncountStart(FieldManager.EncountFadeType.Trainer, trainerID1, trainerID2);
            // SetEventListIndex has no caller in the binary (b096): inlined here as SetCloudScaleEnd + store -1 (02c501f0).
            SetEventListIndex(-1);
            _isCall_TrainerBtl = true;
        }
		public void ForceEyeEncount(global::Dpr.Trainer.TrainerID trainerID) {
            foreach (var moveCode in FieldObjectMoveCodes)
            {
                if (moveCode.TrainerID == trainerID)
                {
                    moveCode.IsForceEyeHit = true;
                    break;
                }
            }
        }
		public bool TrainerEyeCheck(ref global::UnityEngine.Vector3 moveVector, ref global::UnityEngine.Vector2 hitpos) {
            Vector3 subMoveVector = default(Vector3);
            _eyeEncountTarget[0] = null;
            _eyeEncountTarget[1] = null;

            if (FieldManager.Instance.IsMenuOpen)
                return false;

            if (PlayerWork.transitionZoneID != ZoneID.UNKNOWN)
                return false;

            if (FieldManager.Instance.IsEncountUpdate())
                return false;

            if (FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.FLAG_STOP_EYE_ENCOUNT))
                return false;

            PokeParty party = PlayerWork.playerParty;
            bool hit = false;
            for (int i = 0; i < FieldObjectMoveCodes.Count; i++)
            {
                FieldObjectMoveCode moveCode = FieldObjectMoveCodes[i];
                if (moveCode == null)
                    continue;

                if (!moveCode.TrainerEyeUpdate(ref moveVector, ref hitpos))
                    continue;

                if (_eyeEncountTarget[0] == null)
                    _eyeEncountTarget[0] = moveCode;
                else
                    _eyeEncountTarget[1] = moveCode;

                if (FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_PAIR) || party.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE) >= 2)
                {
                    if (_eyeEncountTarget[0] != null && _eyeEncountTarget[1] != null)
                    {
                        hit = true;
                        break;
                    }
                }
                else if (_eyeEncountTarget[0] != null)
                {
                    hit = true;
                    break;
                }

                hit = true;
            }

            if (!hit)
                return false;

            if (_eyeEncountTarget[1] == null && (FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_PAIR) || party.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE) >= 2))
            {
                subMoveVector = Vector3.zero;
                for (int i = 0; i < FieldObjectMoveCodes.Count; i++)
                {
                    FieldObjectMoveCode moveCode = FieldObjectMoveCodes[i];
                    if (moveCode == null)
                        continue;

                    if (_eyeEncountTarget[0] == moveCode)
                        continue;

                    if (!moveCode.TrainerEyeUpdate(ref subMoveVector, ref hitpos))
                        continue;

                    _eyeEncountTarget[1] = moveCode;
                    break;
                }
            }

            FieldCanvas.DeleteBalloon(null, false);
            PlayerInputActive(false, true);
            moveVector = Vector3.zero;
            for (int i = 0; i < _eyeEncountTarget.Length; i++)
            {
                if (_eyeEncountTarget[i] == null)
                    continue;

                _eyeEncountTarget[i].MVCodeEncount();
                TrainerID trainerID = _eyeEncountTarget[i].TrainerID;
                _talkTrinerIndex[i] = -1;
                if (trainerID != TrainerID.NONE && trainerID != TrainerID.MAX)
                    _talkTrinerIndex[i] = (int)trainerID;
            }

            // EyeTrainerSetUp never reads its time argument (no s0 set before the call @02c50814).
            EyeTrainerSetUp(0.0f);
            return true;
        }
		private void OnEyeCallBack(global::FieldObjectMoveCode mvobj) {
            PlayerInputActive(false);

            if (!FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_PAIR) && PlayerWork.playerParty.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE) < 2 && _eyeEncountTarget[0] != null)
                return;

            for (int i = 0; i < _eyeEncountTarget.Length; i++)
            {
                if (_eyeEncountTarget[i] == null)
                {
                    mvobj.MVCodeEncount();
                    _eyeEncountTarget[i] = mvobj;
                    FindTrainerIndex(i, mvobj.TrainerID);
                    break;
                }
            }

            EyeTrainerSetUp(0.0f); // the float argument is never read by EyeTrainerSetUp (tail call @02c50efc)
        }
		private void EyeTrainerSetUp(float time) {
            if (FieldManager.Instance.IsMenuOpen)
                return;

            for (int i = 0; i < _eyeEncountTarget.Length; i++)
            {
                if (_eyeEncountTarget[i] == null)
                    continue;

                var entity = _eyeEncountTarget[i].Entity;
                entity.EventParams.IsEventRunning = true;
                if (entity.EventParams.MoveCodeIndex > -1)
                    FieldObjectMoveCodes[entity.EventParams.MoveCodeIndex].MVCodeStop();
            }

            if (TrainerWork.IsTagTranier(_eyeEncountTarget[0].TrainerID, out TrainerID tagTrainerID))
            {
                for (int i = 0; i < FieldObjectMoveCodes.Count; i++)
                {
                    if (FieldObjectMoveCodes[i] != null && FieldObjectMoveCodes[i].TrainerID == tagTrainerID)
                    {
                        _eyeEncountTarget[1] = FieldObjectMoveCodes[i];
                        FindTrainerIndex(1, tagTrainerID);
                        FieldObjectMoveCodes[i].MVCodeStop();
                        break;
                    }
                }

                if (JumpLabel("ev_trainer_type_tag", null))
                {
                    _hit_object = _eyeEncountTarget[0].Entity;
                    _hit_position = _hit_object.worldPosition;
                    FlagWork.SetWork(EvWork.WORK_INDEX.SCWK_TARGET_OBJID, 0);
                }
            }
            else if (JumpLabel("ev_trainer_move_battle", null))
            {
                _hit_object = _eyeEncountTarget[0].Entity;
                _hit_position = _hit_object.worldPosition;
                if (_eyeEncountTarget[1] != null)
                    _hit_object_sub = _eyeEncountTarget[1].Entity;

                FlagWork.SetWork(EvWork.WORK_INDEX.SCWK_TARGET_OBJID, 0);
            }

            _updateDelegate = null;
        }
		private bool EyeEncount(global::FieldObjectMoveCode mvobj, float time) {
            switch (_eyeEncountSeq)
            {
                case 0:
                    if (!GameManager.fieldCamera.IsMoveStop())
                        return false;

                    _eyeEncountBallon[0] = FieldCanvas.SetBalloon(0, mvobj.Entity.transform);
                    _eyeEncountWait = 0.0f;
                    _eyeEncountSeq++;
                    return false;

                case 1:
                    if (_eyeEncountWait > 1.0f)
                        _eyeEncountSeq = 2;

                    _eyeEncountWait += time;
                    return false;

                case 2:
                    FieldCanvas.DeleteBalloon(_eyeEncountBallon[0]);
                    _eyeEncountBallon[0] = null;
                    _eyeEncountWait = 0.0f;
                    _eyeEncountSeq++;
                    return false;

                case 3:
                    if (!mvobj.PlayerApproach(time))
                        return false;

                    _hit_position = mvobj.Entity.worldPosition;
                    _eyeEncountSeq++;
                    return false;

                default:
                    _eyeEncountSeq = 0;
                    return true;
            }
        }
		private bool EyeEncountTagTrainer(global::FieldObjectMoveCode mvobj1, global::FieldObjectMoveCode mvobj2, float time) {
            switch (_eyeEncountSeq)
            {
                case 0:
                    if (!GameManager.fieldCamera.IsMoveStop())
                        return false;

                    _eyeEncountBallon[0] = FieldCanvas.SetBalloon(0, mvobj1.Entity.transform);
                    _eyeEncountBallon[1] = FieldCanvas.SetBalloon(0, mvobj2.Entity.transform);
                    _eyeEncountWait = 0.0f;
                    _eyeEncountSeq++;
                    return false;

                case 1:
                    if (_eyeEncountWait > 1.0f)
                        _eyeEncountSeq = 2;

                    _eyeEncountWait += time;
                    return false;

                case 2:
                    FieldCanvas.DeleteBalloon(_eyeEncountBallon[0]);
                    FieldCanvas.DeleteBalloon(_eyeEncountBallon[1]);
                    _eyeEncountBallon[0] = null;
                    _eyeEncountBallon[1] = null;
                    _eyeEncountWait = 0.0f;
                    _eyeEncountSeq++;
                    return false;

                case 3:
                    bool isApproach1 = mvobj1.PlayerApproach(time);
                    bool isApproach2 = mvobj2.PlayerApproach(time);
                    if (isApproach1 && isApproach2)
                    {
                        _hit_position = mvobj1.Entity.worldPosition;
                        _eyeEncountSeq++;
                    }
                    return false;

                default:
                    _eyeEncountSeq = 0;
                    return true;
            }
        }
		private void UG_GuruGuruHole(float time) {
            float yawAngle = EntityManager.activeFieldPlayer.yawAngle;
            EntityManager.activeFieldPlayer.isLanding = false;
            switch (_ugSeq)
            {
                case 0:
#if PC_UNLOCKED_FPS
                    EntityManager.activeFieldPlayer.worldPosition.y -= _fallSpd * PcPlatform.PcFrameClock.Frames;
#else
                    EntityManager.activeFieldPlayer.worldPosition.y -= _fallSpd;
#endif
                    EntityManager.activeFieldPlayer.worldPosition.x = _ugEndPos.x;
                    EntityManager.activeFieldPlayer.worldPosition.z = _ugEndPos.z;
                    if (EntityManager.activeFieldPlayer.worldPosition.y <= _ugEndPos.y)
                    {
                        EntityManager.activeFieldPlayer.worldPosition = _ugEndPos;
                        _ugSeq++;
                    }
                    break;

                case 1:
                    if (yawAngle >= 325.0f || yawAngle <= 0.0f)
                    {
                        EntityManager.activeFieldPlayer.yawAngle = 0.0f;
                        _ugSeq++;
                        return;
                    }
                    break;

                case 2:
                    _ugSeq = 3;
                    return;

                default:
                    GameManager.fieldCamera.Target = EntityManager.activeFieldPlayer.transform;
                    EntityManager.activeFieldPlayer.isLanding = true;
                    _updateDelegate = null;
                    PlayerWork.isPlayerInputActive = true;
                    return;
            }

#if PC_UNLOCKED_FPS
            EntityManager.activeFieldPlayer.yawAngle = yawAngle + _fallRotSpd * PcPlatform.PcFrameClock.Frames;
#else
            EntityManager.activeFieldPlayer.yawAngle = yawAngle + _fallRotSpd;
#endif
        }
