		public void UG_EnterOrExit() {
            FieldManager.Instance.ResetSaveZoneBgm();
            DeleteTurearuki();

            bool isUnderGround = ZoneWork.IsUnderGround(PlayerWork.zoneID);
            int x = EntityManager.activeFieldPlayer.gridPosition.x;
            int y = EntityManager.activeFieldPlayer.gridPosition.y;
            if (isUnderGround)
            {
                FlagWork.SetWork(EvWork.WORK_INDEX.WK_SCENE_WILDCARD_002, SingletonMonoBehaviour<UgNetworkManager>.isInstantiated ? 1 : 0);
                SwitchNotification.SetFocusHandlingModeSuspend();
                _ugNextJumpPos = null;
                GotoOnTheGround();

                var playerSaveData = PlayerWork.PlayerSaveData;
                playerSaveData.worpPoint.zenmetu = PlayerWork.ugSaveData.ReturnZenmetsu_Ground;
                PlayerWork.PlayerSaveData = playerSaveData;
            }
            else
            {
                FieldManager.Instance.StopSwayGrass_NextArea();
                SwitchNotification.SetFocusHandlingModeNotify();
                UgFieldManager.isFallEnter = true;
                _ugNextJumpPos = GetUgJumpPosData((y / 32) * 30 + (x / 32));
                GotoUnderGround();

                var playerSaveData = PlayerWork.PlayerSaveData;
                var ugSaveData = PlayerWork.ugSaveData;
                ugSaveData.ReturnZenmetsu_Ground = playerSaveData.worpPoint.zenmetu;
                PlayerWork.ugSaveData = ugSaveData;
            }
        }
