		public bool CheckPlaceData() {
            PlaceData placeData = DataManager.PlaceData["PlaceData_" + _areaID.ToString()];
            Vector2Int grid = EntityManager.activeFieldPlayer.gridPosition;
            for (int i = 0; i < placeData.Data.Length; i++)
