		private void GotoOnTheGround() {
            _ugFallSpdCurrent = _fallDiveSpd;
            Instanse._dummyPlayer.transform.position = EntityManager.activeFieldPlayer.transform.position;
            Sequencer.update += Dpr.SubContents.Utils.PlayerGuruguru;
            Sequencer.update += PlayerRising;
            AudioManager.Instance.PlaySe(AK.EVENTS.S_UND002, null);
            Sequencer.Start(Dpr.SubContents.Utils.PlayerGuruguruStop(0.0f, 9.5f, true, () =>
            {
                EntityManager.activeFieldPlayer.nextSequence = FieldPlayerEntity.SequenceID.Active;
                EntityManager.activeFieldPlayer.isLanding = true;
                if (_ugNextJumpPos == null)
                {
                    EntityManager.activeFieldPlayer.isLanding = false;
                    Vector2Int locator = PlayerWork.ugSaveData.ReturnLocator;
                    ZoneID zone = (ZoneID)PlayerWork.ugSaveData.ReturnZoneID;
                    if (locator == Vector2Int.zero && zone == ZoneID.C01)
                    {
                        locator = new Vector2Int(310, 531);
                        zone = ZoneID.C04;
                    }

                    PlayerWork.SetPlayerGrid(locator);
                    PlayerWork.SetPlayerHeight(PlayerWork.ugSaveData.ReturnHeight);
                    PlayerWork.SetPlayerRotation(0.0f);
                    PlayerWork.IsFromUg = true;
                    Fader.fillColor = Color.white;
                    Fader.FadeOut(0.5f);
                    Sequencer.update += CheckSessionFinish;

                    // <>c__DisplayClass279_0 {zone, this}: allocated inside this block of <GotoOnTheGround>b__279_0 (02ca5dc0),
                    // so the local function lives here (it captures `zone`), not at method scope.
                    void CheckSessionFinish(float deltaTime)
                    {
                        if (GetWork(EvWork.WORK_INDEX.WK_SCENE_WILDCARD_002) == 1)
                        {
                            if (Dpr.NetworkUtils.NetworkManager.Instance.ProcessingInternetGo())
                                return;

                            if (Dpr.NetworkUtils.NetworkManager.SessionState == INL1.IlcaNetSessionState.SS_NoInit)
                                return;

                            SetWork(EvWork.WORK_INDEX.WK_SCENE_WILDCARD_002, 0);
                            Dpr.NetworkUtils.NetworkManager.FinishSession();
                        }
                        else
                        {
                            if (Dpr.NetworkUtils.NetworkManager.IsConnect)
                                return;

                            PlayerWork.SetTransitionZone(zone, -1);
                            Sequencer.update -= CheckSessionFinish;
                        }
                    }
                }
            }));
        }
		private void SetupUgHolePosRot(global::UnityEngine.GameObject ugObject) {
            FieldCalcUgHole.CalcHoleTransform(out Vector3 eulerAngles, out Vector3 positionOffset);
            var localPosition = ugObject.transform.localPosition + positionOffset;
            ugObject.transform.localPosition = localPosition;
            ugObject.transform.eulerAngles = eulerAngles;
        }
		private void GotoUnderGround() {
            if (FieldManager.Instance.NowMapType != MapType.MAPTYPE_TOWN && FieldManager.Instance.NowMapType != MapType.MAPTYPE_ROAD)
                return;

            PlayReportManager.GoUnderGround();
            var player = EntityManager.activeFieldPlayer;
            PlayerWork.ReturnZoneID = (int)PlayerWork.zoneID;
            var grid = player.gridPosition;
            PlayerWork.UgReturnPos = new Vector3(grid.x, player.Height, grid.y);

            if (_ugDiveSeq < 100)
                return;

            PlayerInputActive(false);
            FieldManager.Instance.UG_Hole.SetActive(true);
            FieldManager.Instance.UG_Hole.transform.localScale = new Vector3(0.0f, 0.0f, 0.0f);
            FieldManager.Instance.UG_Hole.transform.SetParent(player.transform.parent);
            SetupUgHolePosRot(FieldManager.Instance.UG_Hole);
            _ugDiveSeq = 0;
            _ugDiveUpdateTime = 0.0f;
            _ugDiveRotTime = 0.0f;
            _ugDiveRotStart = 0.0f;
            _ugDiveRotEnd = 0.0f;
            _ugDiveJumpingTime = 0.0f;
            PlayerWork.IsToUg = true;
            Fader.fillColor = Color.black;
            Cmd_ObjPauseAll();

            if (player.IsRideBicycle())
                player.SetNormalForm(() => _updateDelegate = UG_HoleDive);
            else
                _updateDelegate = UG_HoleDive;
        }
		private void FromUnderGround() {
            PlayerInputActive(false);
            FieldManager.Instance.UG_Hole.SetActive(true);
            FieldManager.Instance.UG_Hole.transform.localScale = new Vector3(2.0f, 2.0f, 2.0f);
            _ugFromSeq = 0;
            _ugFromJumpTime = 0.0f;
            _ugFromRotSpdCurrent = _fromRotSpd;
            _updateDelegate = UG_From;
            _toUgInvisibleObjects.SearchObjects();
            _toUgInvisibleObjects.ChangeScale(0.0f, 0.0f);
        }
