		private void UG_HoleDive(float time) {
            var player = EntityManager.activeFieldPlayer;
            _toUgInvisibleObjects.Update(time);
            switch (_ugDiveSeq)
            {
                case 0:
                {
                    PlayerInputActive(false);
                    _ugDiveRotStart = player.yawAngle;
                    _ugDiveRotEnd = 0.0f;
                    float diffAngle = _ugDiveRotEnd - _ugDiveRotStart;
                    if (diffAngle < 0.0f)
                        diffAngle += 360.0f;

                    diffAngle %= 360.0f;
                    if (diffAngle > 180.0f)
                        diffAngle -= 360.0f;

                    float absAngle = Mathf.Abs(diffAngle);
                    if (absAngle >= 30.0f)
                        player.GetAnimationPlayer().Play(1, 0.2f, 0.0f);

                    _ugDiveUpdateTime = 0.0f;
                    _ugDiveRotTime = absAngle / 540.0f;
                    _toUgInvisibleObjects.SearchObjects();
                    break;
                }

                case 1:
                {
                    _ugDiveUpdateTime += time;
                    float diffAngle = _ugDiveRotEnd - _ugDiveRotStart;
                    if (diffAngle < 0.0f)
                        diffAngle += 360.0f;

                    diffAngle %= 360.0f;
                    float rate = _ugDiveUpdateTime / _ugDiveRotTime;
                    if (rate >= 1.0f)
                    {
                        player.GetAnimationPlayer().Play(0, 0.2f, 0.0f);
                        player.yawAngle = 0.0f;
                        _ugDiveSeq = 10;
                    }
                    else
                    {
                        diffAngle = diffAngle < 180.0f ? diffAngle : diffAngle - 360.0f;
                        player.yawAngle = diffAngle * rate + _ugDiveRotStart;
                    }
                    return;
                }

                case 10:
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_UND001, null);
                    FieldManager.Instance.UG_Hole.transform.localScale = Vector3.zero;
                    FieldManager.Instance.UG_Hole.SetActive(true);
                    _toUgInvisibleObjects.ChangeScale(0.0f, 0.1f);
                    break;

                case 11:
                {
                    Vector3 scale = FieldManager.Instance.UG_Hole.transform.localScale;
                    scale.x += time * 30.0f;
                    if (scale.x >= 2.0f)
                    {
                        _ugDiveSeq++;
                        scale.x = 2.0f;
                    }

                    scale.y = scale.x;
                    scale.z = scale.x;
                    FieldManager.Instance.UG_Hole.transform.localScale = scale;
                    return;
                }

                case 16:
                    player.nextSequence = FieldPlayerEntity.SequenceID.HoleJump;
                    break;

                case 17:
                    _ugDiveJumpingTime += time;
                    if (_ugDiveJumpingTime >= 0.4f)
                    {
                        Fader.FadeOut(0.3f);
                        _ugDiveSeq = 100;
                    }
                    return;

                case 100:
                    if (Fader.isBusy)
                        return;

                    Cmd_ObjPauseClearAll();
                    PlayerWork.isPlayerInputActive = false;
                    FieldManager.Instance.LockHoleEnd();
                    _updateDelegate = null;
                    player.nextSequence = FieldPlayerEntity.SequenceID.Active;
                    EntityManager.activeFieldPlayer.isLanding = true;
                    FieldManager.Instance.UG_Hole.transform.SetParent(player.transform);
                    FieldManager.Instance.UG_Hole.transform.SetLocalRotationEuler(_ugHoleRot);
                    FieldManager.Instance.UG_Hole.transform.SetLocalPositionY(0.1f);
                    PlayerWork.SetPlayerGrid(Vector2Int.FloorToInt(_ugNextJumpPos.Locators));
                    PlayerWork.SetPlayerHeight(0.0f);
                    PlayerWork.SetPlayerRotation(0.0f);
                    FieldManager.Instance.ResetSaveZoneBgm();
                    PlayerWork.SetTransitionZone(_ugNextJumpPos.ZoneID, -1);
                    _toUgInvisibleObjects.Reset();
                    return;
            }

#if PC_UNLOCKED_FPS
            // PC (s37): steps 12..15 have no case - they are a 4-frame wait before the hole jump; advance them on 30 Hz ticks.
            if (_ugDiveSeq >= 12 && _ugDiveSeq <= 15)
                _ugDiveSeq = Mathf.Min(_ugDiveSeq + PcPlatform.PcFrameClock.Ticks, 16);
            else
                _ugDiveSeq++;
#else
            _ugDiveSeq++;
#endif
        }
		private void UG_From(float time) {
            var player = EntityManager.activeFieldPlayer;
            _toUgInvisibleObjects.Update(time);
            switch (_ugFromSeq)
            {
                case 0:
                    if (!player.gameObject.activeInHierarchy)
                        return;

                    FieldManager.Instance.UG_Hole.transform.SetParent(player.transform.parent);
                    SetupUgHolePosRot(FieldManager.Instance.UG_Hole);
                    player.isLanding = false;
                    player.transform.SetPositionY(player.transform.position.y - 2.0f);
                    break;

                case 1:
                    if (Fader.isBusy)
                        return;
                    break;

                case 2:
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_UND002_2, null);
                    player.nextSequence = FieldPlayerEntity.SequenceID.HoleOutJump;
                    break;

                case 3:
                {
                    _ugFromJumpTime += time;
                    float rate = _ugFromJumpTime / 0.6f;
                    if (rate > 1.0f)
                        rate = 1.0f;

                    player.yawAngle = Mathf.Lerp(0.0f, 360.0f, rate);
                    if (rate >= 1.0f)
                    {
                        _ugFromJumpTime = 0.0f;
                        _ugFromSeq++;
                    }
                    return;
                }

                case 4:
                {
                    _ugFromJumpTime += time;
                    float rate = _ugFromJumpTime / 0.4f;
                    if (rate > 1.0f)
                        rate = 1.0f;

                    player.yawAngle = Mathf.Lerp(0.0f, 360.0f, rate);
                    if (rate >= 1.0f)
                        _ugFromSeq++;
                    return;
                }

                case 5:
                {
#if PC_UNLOCKED_FPS
                    float rotSpd = _ugFromRotSpdCurrent - _fromRotAcce * PcPlatform.PcFrameClock.Frames;
#else
                    float rotSpd = _ugFromRotSpdCurrent - _fromRotAcce;
#endif
                    if (rotSpd < _fromRotSpdMin)
                        rotSpd = _fromRotSpdMin;

                    _ugFromRotSpdCurrent = rotSpd;
                    float yawAngle = player.yawAngle + rotSpd * 30.0f * time;
                    if (rotSpd <= _fromRotSpdMin && yawAngle >= 360.0f)
                    {
                        player.yawAngle = 0.0f;
                        _toUgInvisibleObjects.ChangeScale(1.0f, 0.1f);
                        break;
                    }

                    player.yawAngle = yawAngle;
                    return;
                }

                case 6:
                {
                    Vector3 scale = FieldManager.Instance.UG_Hole.transform.localScale;
                    scale.x -= time * 20.0f;
                    if (scale.x <= 0.0f)
                    {
                        scale.x = 0.0f;
                        _ugFromSeq = 100;
                    }

                    scale.y = scale.x;
                    scale.z = scale.x;
                    FieldManager.Instance.UG_Hole.transform.localScale = scale;
                    return;
                }

                case 100:
                    Fader.fillColor = Color.black;
                    PlayerInputActive(false);
                    FieldManager.Instance.UG_Hole.transform.SetParent(player.transform);
                    FieldManager.Instance.UG_Hole.transform.SetLocalRotationEuler(_ugHoleRot);
                    FieldManager.Instance.UG_Hole.transform.SetLocalPositionY(0.1f);
                    FieldManager.Instance.UG_Hole.SetActive(false);
                    _toUgInvisibleObjects.Reset();
                    player.isLanding = true;
                    _updateDelegate = null;
                    return;

                default:
                    // Shipped quirk: an unknown _ugFromSeq advances the DIVE sequence (ldr/str [this,#0x200] @02c54618).
                    _ugDiveSeq++;
                    return;
            }

            _ugFromSeq++;
        }
