		public bool CheckEventObjectGrid(int x, int y, float height) {
            foreach (var character in EntityManager.fieldCharacters)
            {
                if (CheckEventObjectGridCore(character, x, y, height))
                    return true;
            }

            foreach (var pokemon in EntityManager.fieldPokemons)
            {
                if (CheckEventObjectGridCore(pokemon, x, y, height))
                    return true;
            }

            return false;
        }
		private static bool CheckEventObjectGridCore(global::FieldObjectEntity entity, int x, int y, float height) {
            if (entity == null)
                return false;

            if (entity == EntityManager.activeFieldPlayer)
                return false;

            if (!entity.gameObject.activeInHierarchy)
                return false;

            var grid = entity.gridPosition;
            if (grid.x != x || grid.y != y)
                return false;

            float diffHeight = entity.worldPosition.y - height;
            if (diffHeight < -1.0f || diffHeight > 1.0f)
                return false;

            return true;
        }
		private void EntityMoveCodeCheck() {
            var player = EntityManager.activeFieldPlayer;
            int gx = player.gridPosition.x;
            int gz = player.gridPosition.y;
            float height = player.Height;

            FieldObjectMoveCodes.RemoveAll(obj => obj == null || obj.IsMissing());
            _fieldObjectEntity.RemoveAll(obj => obj == null);

            int entityCount = _fieldObjectEntity.Count;
            int moveCodeCount = FieldObjectMoveCodes.Count;

            for (int i = 0; i < entityCount; i++)
                _fieldObjectEntity[i].EventParams.FieldObjectIndex = i;

            for (int i = 0; i < moveCodeCount; i++)
            {
                var moveCode = FieldObjectMoveCodes[i];
                moveCode.SetPlayerDistance(gx, gz, height);
                moveCode.Entity.EventParams.MoveCodeIndex = i;

                var nearObject = moveCode.Entity.EventParams.NearObject;
                for (int j = 0; j < nearObject.Length; j++)
                    nearObject[j] = EntityParam.NearNone;
            }

            ZoneID zoneID = PlayerWork.zoneID;
            for (int i = 0; i < moveCodeCount; i++)
            {
                var entity = FieldObjectMoveCodes[i].Entity;
                var param = entity.EventParams;
                if (param.LocaitionZoneID != zoneID)
                    continue;

                Vector3 position = entity.worldPosition;
                for (int j = param.FieldObjectIndex + 1; j < entityCount; j++)
                {
                    var other = _fieldObjectEntity[j];
                    if (!other.gameObject.activeInHierarchy)
                        continue;

                    // NaN-exact: b.ge skips only on an ordered >= (02c44560).
                    float dy = other.worldPosition.y - position.y;
                    if (dy * dy >= 1.5f)
                        continue;

                    // fcmp + fccmp hi (02c4457c): skip only when both are "> 1 or unordered".
                    float dx = other.worldPosition.x - position.x;
                    float dz = other.worldPosition.z - position.z;
                    if (dx * dx <= 1.0f || dz * dz <= 1.0f)
                    {
                        var otherNear = other.EventParams.NearObject;
                        for (int k = 0; k < otherNear.Length; k++)
                        {
                            if (otherNear[k] == EntityParam.NearNone)
                            {
                                otherNear[k] = param.FieldObjectIndex;
                                break;
                            }
                        }

                        var near = param.NearObject;
                        for (int k = 0; k < near.Length; k++)
                        {
                            if (near[k] == EntityParam.NearNone)
                            {
                                near[k] = j;
                                break;
                            }
                        }
                    }
                }
            }
        }
		private bool SetNearIndex(ref global::Dpr.EvScript.EvDataManager.EntityParam param, int index) {
            for (int i = 0; i < param.NearObject.Length; i++)
            {
                if (param.NearObject[i] == EntityParam.NearNone)
                {
                    param.NearObject[i] = index;
                    return true;
                }
            }

            return false;
        }
