		private global::System.Collections.IEnumerator TurnEnumerator(int index) {
            if (index == 0)
            {
                if (EntityManager.activeFieldPlayer == null)
                    yield break;

                while (!ObjectTurn(_deltatime, _turnEndFrame_Obj, ref EntityManager.activeFieldPlayer.worldPosition, _hit_object, 0))
                    yield return null;
            }
            else
            {
                if (_hit_object == null)
                    yield break;

                while (!ObjectTurn(_deltatime, _turnEndFrame_Hero, ref _hit_position, EntityManager.activeFieldPlayer, 1))
                    yield return null;
            }
        }
