		private bool ObjectTurn(float time, float endtime, ref global::UnityEngine.Vector3 target, global::FieldObjectEntity myEntity, int index) {
            if (myEntity == null)
                return true;

            var animationPlayer = myEntity.GetAnimationPlayer();
            if (animationPlayer == null)
            {
                _turnTime[index] = 0.0f;
                return true;
            }

            if (_turnTime[index] == 0.0f)
            {
                _turnEndQuaternion[index] = Quaternion.LookRotation(target - myEntity.worldPosition);
                float diffAngle = myEntity.yawAngle - _turnEndQuaternion[index].eulerAngles.y;
                _turnDiffFlag[index] = diffAngle > -30.0f && diffAngle < 30.0f;

                var character = myEntity as FieldCharacterEntity;
                if (character != null)
                    character.IsStopFootEffect = true;
            }

            if (endtime <= 0.0f)
            {
                myEntity.yawAngle = _turnEndQuaternion[index].eulerAngles.y;
                _turnTime[index] = 0.0f;
                animationPlayer.Play(FieldObjectEntity.GetIdleAnimation(myEntity), 0.2f, 0.0f);

                var character = myEntity as FieldCharacterEntity;
                if (character != null)
                    character.IsStopFootEffect = false;

                return true;
            }

            _turnTime[index] += time;
            float rate = _turnTime[index] / endtime;
            if (rate > 1.0f)
            {
                myEntity.yawAngle = _turnEndQuaternion[index].eulerAngles.y;
                _turnTime[index] = 0.0f;

                var player = myEntity as FieldPlayerEntity;
                if (player == null)
                    animationPlayer.Play(FieldObjectEntity.GetIdleAnimation(myEntity), 0.2f, 0.0f);
                else
                    player.PlayIdle();

                var character = myEntity as FieldCharacterEntity;
                if (character != null)
                    character.IsStopFootEffect = false;

                return true;
            }

#if PC_UNLOCKED_FPS
            myEntity.yawAngle = Quaternion.Lerp(myEntity.transform.rotation, _turnEndQuaternion[index], 1f - Mathf.Pow(1f - rate, PcPlatform.PcFrameClock.Frames)).eulerAngles.y;
#else
            myEntity.yawAngle = Quaternion.Lerp(myEntity.transform.rotation, _turnEndQuaternion[index], rate).eulerAngles.y;
#endif
            if (!_turnDiffFlag[index])
            {
                var player = myEntity as FieldPlayerEntity;
                if (player == null)
                    animationPlayer.Play(FieldObjectEntity.GetWalkAnimation(myEntity), 0.2f, 0.0f);
                else
                    player.PlayWalk();
            }

            return false;
        }
