		private bool CmdPlayerMoveGridCenter(global::EvData.Command data) {
            int dir = GetArgInt(data.Arg[1]);
            var player = EntityManager.activeFieldPlayer;

            switch (_talkStart)
            {
                case TalkState.Init:
                {
                    _talkStart = TalkState.EndWait;
                    player.PlayWalk();
                    _moveGridCenterStart = player.transform.rotation;

                    Vector3 euler = Vector3.zero;
                    switch (dir)
                    {
                        case 1: euler.y = 270.0f; break;
                        case 2: euler.y = 0.0f; break;
                        case 3: euler.y = 90.0f; break;
                        default: euler.y = 180.0f; break;
                    }
                    _moveGridCenterEnd.eulerAngles = euler;
                    _turnTime[0] = 0.0f;

                    Vector2 pos = new Vector2(player.worldPosition.x, player.worldPosition.z);
                    Vector2 grid = new Vector2(-player.gridPosition.x, player.gridPosition.y);
                    _playerMoveGridCenterAngle = grid - pos;
                    _playerMoveGridCenterAngle.Normalize();
                    return false;
                }

                case TalkState.EndWait:
                {
                    Vector2 pos = new Vector2(player.worldPosition.x, player.worldPosition.z);
                    Vector2 grid = new Vector2(-player.gridPosition.x, player.gridPosition.y);
                    Vector2 diff = grid - pos;
                    float sqrMagnitude = diff.sqrMagnitude;

#if PC_UNLOCKED_FPS
                    float pcStep = 0.05f * PcPlatform.PcFrameClock.Frames;
                    if (diff.x > pcStep)
                        diff.x = pcStep;
                    else if (diff.x < -pcStep)
                        diff.x = -pcStep;

                    if (diff.y > pcStep)
                        diff.y = pcStep;
                    else if (diff.y < -pcStep)
                        diff.y = -pcStep;
#else
                    if (diff.x > 0.05f)
                        diff.x = 0.05f;
                    else if (diff.x < -0.05f)
                        diff.x = -0.05f;

                    if (diff.y > 0.05f)
                        diff.y = 0.05f;
                    else if (diff.y < -0.05f)
                        diff.y = -0.05f;
#endif

                    player.worldPosition.x += diff.x;
                    player.worldPosition.z += diff.y;

                    if (sqrMagnitude >= 0.05f)
                    {
                        player.yawAngle = (float)Math.Atan2(_playerMoveGridCenterAngle.x, _playerMoveGridCenterAngle.y) * Mathf.Rad2Deg;
                        return false;
                    }

                    _turnTime[0] += _deltatime;
                    float rate = _turnTime[0] / 0.1f;
                    player.yawAngle = Quaternion.Lerp(_moveGridCenterStart, _moveGridCenterEnd, rate).eulerAngles.y;
                    if (rate > 1.0f)
                    {
                        player.GetAnimationPlayer().Play(0);
                        _turnTime[0] = 0.0f;
                        _talkStart = TalkState.Init;
                        return true;
                    }
                    return false;
                }

                default:
                    return false;
            }
        }
