		private bool CmdGetRelPosHero(global::Dpr.EvScript.EvScriptData ev) {
            EvData.Command command = ev.GetScript.Commands[ev.CommandIndex];
            FieldObjectEntity entity = Find_fieldObjectEntity(GetArgString(ev, command.Arg[1]));

            // Numeric-keypad layout of the hero relative to the entity:
            // rows 7/4/1 (hero one grid above / level / below), columns +0/+1/+2.
            int relPos = 0;
            if (entity != null)
            {
                int heroX = EntityManager.activeFieldPlayer.gridPosition.x;
                int heroY = EntityManager.activeFieldPlayer.gridPosition.y;
                int entityX = entity.gridPosition.x;
                int entityY = entity.gridPosition.y;

                if (heroY == entityY - 1)
                    relPos = 7;
                else if (heroY == entityY)
                    relPos = 4;
                else if (heroY == entityY + 1)
                    relPos = 1;

                if (relPos != 0)
                {
                    if (heroX == entityX - 1)
                    {
                    }
                    else if (heroX == entityX)
                        relPos += 1;
                    else if (heroX == entityX + 1)
                        relPos += 2;
                    else
                        relPos = 0;
                }
            }

            FlagWork.SetWork((EvWork.WORK_INDEX)command.Arg[2].data, relPos);
            return true;
        }
		private bool CmdSxyExitPosChange(global::EvData.Command data) {
            int mdIndex = GetArgInt(data.Arg[1]);
            int x = GetArgInt(data.Arg[2]);
            int y = GetArgInt(data.Arg[3]);
            for (int i = 0; i < _warpList.Count; i++)
            {
                FieldEventDoorEntity door = _warpList[i] as FieldEventDoorEntity;
                if (door == null)
                    continue;

                for (int j = 0; j < door.mdIndexArray.Length; j++)
                {
                    if (door.mdIndexArray[j] == mdIndex)
                    {
                        door.gridPositionDirect = new Vector2Int(x, y);
                        return true;
                    }
                }
            }
            return true;
        }
		private global::Dpr.Trainer.TrainerID GetArgTrainerID(global::Dpr.EvScript.EvScriptData ev, global::EvData.Aregment arg) {
            if (arg.argType == global::EvData.ArgType.Float)
                return (TrainerID)(int)SmartPoint.AssetAssistant.UnityExtensions.FloatBits.ToFloat(arg.data);

            if (arg.argType == global::EvData.ArgType.Work)
                return (TrainerID)FlagWork.GetWork((EvWork.WORK_INDEX)arg.data);

            if (arg.argType == global::EvData.ArgType.String)
            {
                string name = ev.EvData.GetString(arg.data);
                for (TrainerID id = TrainerID.NONE; id < TrainerID.MAX; id++)
                {
                    if (name == id.ToString())
                        return id;
                }
            }

            return TrainerID.NONE;
        }
