            int monsNo = GetArgInt(_evArg[1]);
            ushort level = (ushort)GetArgInt(_evArg[2]);
            ushort itemNo = (ushort)GetArgInt(_evArg[3]);
            InitialSpec spec = new InitialSpec();
            spec.monsno = (MonsNo)monsNo;
            spec.level = level;
            if (_evArg.Length > 5)
                spec.talentVNum = (byte)GetArgInt(_evArg[5]);

            PokemonParam param = new PokemonParam(spec);
            if (itemNo != 0)
                param.SetItem(itemNo);

            poketool.poke_memo.poketool_poke_memo.SetFromCapture(param, PlayerWork.playerStatus, PlayerWork.zoneID);
            bool isAdd = PlayerWork.playerParty.AddMember(param);
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[4].data, isAdd ? 1 : 0);
            ZukanWork.SetPoke(param, GET_STATUS.GET);
            FieldPoketch.AddPokemonHistory(param);
            return true;
        }
		private bool EvCmdAddPokemonUI() {
            if (_azukariyaSequence == 0)
            {
                UIZukanRegister window = UIManager.Instance.CreateUIWindow<UIZukanRegister>(UIWindowID.ZUKAN_REGISTER);
                window.OnComplete += addMemberResult =>
                {
                    FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[4].data, 0);
                    _azukariyaSequence = -1;
                };

                int monsNo = GetArgInt(_evArg[1]);
                ushort level = (ushort)GetArgInt(_evArg[2]);
                ushort itemNo = (ushort)GetArgInt(_evArg[3]);
                InitialSpec spec = new InitialSpec();
                spec.monsno = (MonsNo)monsNo;
                spec.level = level;
                if (_evArg.Length > 5)
                    spec.talentVNum = (byte)GetArgInt(_evArg[5]);

                PokemonParam param = new PokemonParam(spec);
                if (itemNo != 0)
                    param.SetItem(itemNo);

                poketool.poke_memo.poketool_poke_memo.SetFromCapture(param, PlayerWork.playerStatus, PlayerWork.zoneID);
                if (FlagWork.GetWork(EvWork.WORK_INDEX.WK_SCENE_KASEKI_MONSNO) == monsNo)
                    PlayerWork.playReportDataRef.fossil_restore++;

                window.Open(param, false);
                _azukariyaSequence = 1;
            }
            return _azukariyaSequence < 0;
        }
