		private bool EvCmdChkPokeWazaGroup() {
            int wazaNo = GetArgInt(_evArg[2]);
            PokeParty party = PlayerWork.playerParty;
            int count = (int)party.GetMemberCount();
            int result = PokeParty.MEMBER_INDEX_ERROR;
            for (int i = 0; i < count; i++)
            {
                PokemonParam param = party.GetMemberPointer((uint)i);
                if (CheckValidPokemonParam(param) && param.HaveWaza((WazaNo)wazaNo))
                {
                    result = i;
                    break;
                }
            }
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, result);
            return true;
        }
