		private bool EvCmdBtlSearcherEventCall() {
            switch (btlsearchSeq)
            {
                case 0:
                    int result = FieldBattleSearcher.TrainerSearch();
                    FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, result);
                    FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[2].data, 100 - PlayerWork.BtlSearcherCharge);
                    btlsearchSeq = 2;
                    if (result == 0)
                    {
                        FlagWork.SetSysFlag(EvWork.SYSFLAG_INDEX.FLAG_STOP_EYE_ENCOUNT, true);
                        btlserchAudio = AudioManager.Instance.CreateSe(AK.EVENTS.S_FI037, 0);
                        btlserchAudio.Play(instance => btlserchAudio = null, false);
                        btlsearchSeq = 1;
                    }
                    return false;

                case 1:
                    if (btlserchAudio != null)
                        return false;

                    btlsearchSeq = 2;
                    return false;

                case 2:
                    btlsearchSeq = 0;
                    return true;

                default:
                    btlsearchSeq = 0;
                    return false;
            }
        }
