		private bool EvCmdNameInPoke() {
            PokemonParam pokemonParam;
            int trayIndex;
            int index;
            if (_softwareKeyboardSubState != 0)
                return false;

            _softwareKeyboardSubState = 1;
            index = GetArgInt(_evArg[1]);
            trayIndex = GetArgInt(_evArg[2]);
            pokemonParam = GetPokemonParam(trayIndex, index);

            string messageLabel;
            switch (pokemonParam.GetSex())
            {
                case Sex.MALE:
                    messageLabel = "SS_strinput_006";
                    break;
                case Sex.FEMALE:
                    messageLabel = "SS_strinput_007";
                    break;
                default:
                    messageLabel = "SS_strinput_005";
                    break;
            }
            // shipped: the nickname is read and discarded (02c6a904)
            pokemonParam.GetNickName();
            string headerText = SoftwareKeyboard.GetMessageText(messageLabel);

            SoftwareKeyboard.Param param = new SoftwareKeyboard.Param();
            param.text = "";
            param.textMinLength = 1;
            param.textMaxLength = SoftwareKeyboard.LanguageMaxLength(6);
            param.headerText = headerText;
            param.subText = null;
            param.guideText = null;
            param.okText = null;
            param.invalidCharFlag = SoftwareKeyboard.InvalidChar.AtMark;
            SoftwareKeyboard.Open(param, (resultText, errorState) => SoftwareKeyboard.InputCheck(resultText, errorState), (isSuccess, resultText) =>
            {
                if (isSuccess)
                {
                    pokemonParam.SetNickName(resultText);
                    if (trayIndex >= 0)
                        Dpr.Box.BoxPokemonWork.UpdatePokemon(pokemonParam, trayIndex, index);
                }
                SetWork(_evArg[3].data, (!isSuccess || string.IsNullOrEmpty(resultText)) ? 1 : 0);
                _softwareKeyboardSubState = 0;
            });
            return _softwareKeyboardSubState == 0;
        }
