		private bool EvCmdColosseumMapChangeIn() {
            int netType = GetArgInt(_evArg[1]);
            int rule = GetArgInt(_evArg[2]);
            int matchType = GetArgInt(_evArg[3]);
            MatchingParam matchingParam = new MatchingParam();
            ColiseumRoomManager roomManager = new GameObject("ColiseumRoomManager").AddComponent<ColiseumRoomManager>();
            ZoneID zoneID = PlayerWork.zoneID;
            roomManager.SetZoneData(zoneID, PlayerWork.locatorIndex, PlayerWork.grid);

            Dpr.NetworkUtils.MatchingType matchingType;
            if (matchType == 1)
            {
                matchingParam.password = PlayerWork.RandomGroup.group[1].group_name;
                matchingType = Dpr.NetworkUtils.MatchingType.Group;
            }
            else
            {
                matchingType = matchingPassword.Length > 0 ? Dpr.NetworkUtils.MatchingType.Password : Dpr.NetworkUtils.MatchingType.Random;
                matchingParam.password = matchingPassword.ToString();
            }
            FlagWork.SetWork(EvWork.WORK_INDEX.UNION_TEMP0, (int)zoneID);

            matchingParam.SessionMaxPlayerCount = (rule == 0 || rule == 1) ? UnionWork.COLISEUM_MAX_PLAYER_NUM_NOT_MULTI : UnionWork.COLISEUM_MAX_PLAYER_NUM_MULTI;
            Dpr.NetworkUtils.BattleModeID battleModeID = rule == 2 ? Dpr.NetworkUtils.BattleModeID.Multi : (rule == 1 ? Dpr.NetworkUtils.BattleModeID.Double : Dpr.NetworkUtils.BattleModeID.Single);
            roomManager.SetBattleRule(battleModeID);

            INL1.IlcaNetSessionNetworkType connectType = netType != 0 ? INL1.IlcaNetSessionNetworkType.Internet : INL1.IlcaNetSessionNetworkType.Local;
            matchingParam.startMode = INL1.IlcaNetSessionGamingStartMode.Natural;
            matchingParam.GameModeID = Dpr.NetworkUtils.NetworkHelper.CreateBattleGameMode(matchingType, battleModeID, connectType);
            matchingParam.netType = connectType;
            roomManager.SetMatchingParam(matchingParam);

            PlayerWork.SetTransitionZone(ZoneID.UNION03, 0);
            matchingPassword.Clear();
            return true;
        }
