		private bool EvCmdKabeNobori() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_hidenSequence)
            {
                case RockClimbSequence_None:
                {
                    FieldObjectEntity eventObject = GetFieldObject(FlagWork.GetWork(EvWork.WORK_INDEX.SCWK_TARGET_OBJID));
                    if (eventObject == null)
                    {
                        _hidenSequence = -1;
                        break;
                    }

                    Vector3 climbStart;
                    player.CalcRockClimbingTargetPosition(eventObject, out climbStart, out _rockClimbingEndPos, out _rockClimbingStandPos);
                    player.isLanding = false;
                    _fieldObjectMove.SetObjectEntity(player);
                    _fieldObjectMove.JumpHeight = DataManager.FieldCommonParam[(int)ParamIndx.RockClimb_StartJumpHeight].param;
                    _fieldObjectMove.MoveTime(climbStart, DataManager.FieldCommonParam[(int)ParamIndx.RockClimb_StartJumpTime].param);

                    Vector3 dir = _rockClimbingEndPos - climbStart;
                    float yaw;
                    if (Mathf.Abs(dir.x) < Mathf.Abs(dir.z))
                        yaw = dir.z > 0.0f ? 0.0f : 180.0f;
                    else
                        yaw = dir.x > 0.0f ? 90.0f : 270.0f;

                    _fieldObjectRotateYaw.SetObjectEntity(player);
                    _fieldObjectRotateYaw.MoveTime(yaw, 0.1f);
                    player.PlayJumpStart();
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI005, null);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI035, null);
                    _hidenSequence++;
                    break;
                }

                case RockClimbSequence_JumpUp:
                    if (player.GetAnimationPlayer().IsPlayingEnd || !_fieldObjectMove.IsBusy)
                    {
                        player.PlayJumpLoop();
                        _hidenSequence++;
                    }
                    break;

                case RockClimbSequence_JumpLoop:
                {
                    if (_fieldObjectMove.IsBusy)
                        break;

                    player.ResetBiidaruOffset();
                    player.beadaruVisibility = true;
                    if (player.worldPosition.y < _rockClimbingEndPos.y)
                        player.PlayRockClimbUp();
                    else
                        player.PlayRockClimbDown();

                    float moveSpeed = DataManager.FieldCommonParam[(int)ParamIndx.RockClimb_MoveSpd].param;
                    _fieldObjectMove.JumpHeight = 0.0f;
                    _fieldObjectMove.MoveSpeed(_rockClimbingEndPos, moveSpeed);
                    FieldManager.Instance.CallEffect(EffectFieldID.EF_F_WAZA_ROCKCLIMB_IN, player.transform, null, null);
                    player.PlayRockClimbEffect();
                    _hidenSequence++;
                    break;
                }

                case RockClimbSequence_Climb:
                    if (_fieldObjectMove.IsBusy)
                        break;

                    player.beadaruVisibility = false;
                    _fieldObjectMove.JumpHeight = DataManager.FieldCommonParam[(int)ParamIndx.RockClimb_EndJumpHeight].param;
                    _fieldObjectMove.MoveTime(_rockClimbingStandPos, DataManager.FieldCommonParam[(int)ParamIndx.RockClimb_EndJumpTime].param);
                    player.PlayJumpStart();
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI005, null);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI035_END, null);
                    FieldManager.Instance.CallEffect(EffectFieldID.EF_F_WAZA_ROCKCLIMB_OUT, player.transform, null, null);
                    player.StopRockClimbEffect();
                    _hidenSequence++;
                    break;

                case RockClimbSequence_EndJumpUp:
                    if (player.GetAnimationPlayer().IsPlayingEnd)
                    {
                        player.PlayJumpLoop();
                        _hidenSequence++;
                    }
                    break;

                case RockClimbSequence_EndJumpLoop:
                    if (_fieldObjectMove.IsBusy)
                        break;

                    player.PlayJumpEnd();
                    _hidenSequence++;
                    break;

                case RockClimbSequence_EndJumpEnd:
                    if (!player.GetAnimationPlayer().IsPlayingEnd)
                        break;

                    player.beadaruVisibility = false;
                    player.isLanding = true;
                    if (_rideBicycleReserve)
                    {
                        _hidenSequence++;
                        player.SetRideBicycle(() => _hidenSequence = -1);
                        FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CYCLE_RIDE, player.transform, null, null);
                    }
                    else
                    {
                        _hidenSequence = -1;
                    }
                    CreateTurearuki();
                    break;
            }
            return _hidenSequence == -1;
        }
		private bool EvCmdNaminori() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            switch (_hidenSequence)
            {
                case 0:
                {
                    FieldManager.Instance.StopSwayGrass_NextArea();
                    player.PlayNaminoriStart();
                    player.isLanding = false;
                    _fieldObjectMove.SetObjectEntity(player);
                    Vector3 targetPos = player.CalcSwimTargetPosition();
                    float moveTime = player.GetAnimationPlayer().currentRemaingTime - 0.56666666f;
                    _fieldObjectMove.MoveTime(targetPos, moveTime);
                    player.AppearSwimBiidaru((targetPos - player.worldPosition).magnitude, moveTime);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI033_START, null);
                    FieldManager.Instance.CallEffect(EffectFieldID.EF_F_WAZA_SURF_IN, player.BiidaruTransform, new Vector3(0.0f, 0.5f, 0.0f), null, null);
                    FieldManager.Instance.SetBgmEvent(AK.EVENTS.B_OTH005);
                    _hidenSequence++;
                    break;
                }

                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;

                    player.ForcePlayNaminoriEffect = true;
                    player.PlaySwimEffect();
                    _hidenSequence++;
                    break;

                case 2:
                    if (!player.GetAnimationPlayer().IsPlayingEnd)
                        break;

                    player.ChangeSwim(true);
                    player.PlayIdle();
                    player.ForcePlayNaminoriEffect = false;
                    player.StopSwimEffect();
                    _hidenSequence = -1;
                    break;
            }
            return _hidenSequence < 0;
        }
