		private bool EvCmdTakinobori() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_hidenSequence)
            {
                case 0:
                {
                    _takiTargetPosition = player.CalcWaterfallUpTargetPosition();
                    Vector3 targetPos = player.worldPosition;
                    targetPos.x = _takiTargetPosition.x;
                    float moveLength = DataManager.FieldCommonParam[(int)ParamIndx.Takinobori_PreMoveLength].param;
                    float yaw;
                    if (player.worldPosition.z < _takiTargetPosition.z)
                    {
                        targetPos.z += moveLength;
                        yaw = 0.0f;
                    }
                    else
                    {
                        targetPos.z -= moveLength;
                        yaw = 180.0f;
                    }
                    _fieldObjectMove.SetObjectEntity(player);
                    _fieldObjectMove.MoveTime(targetPos, DataManager.FieldCommonParam[(int)ParamIndx.Takinobori_PreMoveTime].param);
                    _fieldObjectRotateYaw.SetObjectEntity(player);
                    _fieldObjectRotateYaw.MoveTime(yaw, 0.1f);
                    player.ForcePlayNaminoriEffect = true;
                    player.PlayWaterFallUpEffect();
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI036, null);
                    _hidenSequence++;
                    break;
                }

                case 1:
                {
                    if (_fieldObjectMove.IsBusy)
                        break;

                    Vector3 targetPos = _takiTargetPosition;
                    targetPos.z = player.worldPosition.z;
                    _fieldObjectMove.MoveTime(targetPos, DataManager.FieldCommonParam[(int)ParamIndx.Takinobori_UpTime].param);
                    _hidenSequence++;
                    break;
                }

                case 2:
                    if (_fieldObjectMove.IsBusy)
                        break;

                    _fieldObjectMove.MoveTime(_takiTargetPosition, DataManager.FieldCommonParam[(int)ParamIndx.Takinobori_MoveTime].param);
                    _hidenSequence++;
                    break;

                case 3:
                    if (_fieldObjectMove.IsBusy)
                        break;

                    _mistPlate.Update(PlayerWork.zoneID);
                    player.ForcePlayNaminoriEffect = false;
                    player.StopSwimEffect();
                    _hidenSequence = -1;
                    break;
            }
            return _hidenSequence == -1;
        }
