            cutIn.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            _fieldFloatMove.Update(_deltatime);
            switch (_cutinState)
            {
                case CutInState.None:
                {
                    if (wazaNo == WazaNo.NAMINORI || wazaNo == WazaNo.ANAWOHORU || wazaNo == WazaNo.TEREPOOTO || wazaNo == WazaNo.ROKKUKURAIMU || wazaNo == WazaNo.SORAWOTOBU)
                        DeleteTurearuki();

                    bool isOnBridge = false;
                    if (player.IsRideBicycle())
                    {
                        Vector2Int grid = player.gridPosition;
                        if (GameManager.IsHighAttribute(GameManager.GetAttributeExCodeRaw(grid), player.worldPosition.y))
                        {
                            GameManager.GetAttribute(grid, out code, out stop, false);
                            isOnBridge = AttributeID.MATR_IsBridgeV(code) || AttributeID.MATR_IsBridgeH(code);
                        }
                    }

                    if (!isOnBridge && CheckHidenWazaForceResetForm(wazaNo))
                    {
                        if (wazaNo == WazaNo.ROKKUKURAIMU)
                            _rideBicycleReserve = true;
                        else
                            FieldManager.Instance.SetWwiseEvent(AK.EVENTS.FADEIN_OFF);

                        _cutinState = CutInState.ResetForm;
                        player.SetNormalForm(() => _cutinState = CutInState.PostResetForm);
                    }
                    else
                    {
                        _cutinState = CutInState.PostResetForm;
                    }
                    break;
                }

                case CutInState.PostResetForm:
                {
                    if (PlayerWork.UsedFieldWazaInArea.Contains(wazaNo))
                    {
                        _cutinState = CutInState.End;
                        break;
                    }

                    bool usePokemon;
                    MonsNo monsNo = GetHidenWazaMonsNo(wazaNo);
                    if (monsNo != MonsNo.NULL)
                    {
                        cutIn.Load(monsNo);
                        usePokemon = false;
                    }
                    else
                    {
                        cutIn.Load(GetPokemonParam(-1, PlayerWork.UsedFieldWazaTemotiNo));
                        usePokemon = true;
                    }

                    if (wazaNo == WazaNo.SORAWOTOBU)
                    {
                        if (!player.IsRideBicycle())
                        {
                            _fieldObjectRotateYaw.SetObjectEntity(player);
                            _fieldObjectRotateYaw.MoveSpeed(0.0f, 360.0f);
                            if (_fieldObjectRotateYaw.FloatMove.TargetTime > 0.1f)
                                player.PlayWalk();

                            _cutinState = CutInState.Rotate;
                            break;
                        }
                    }
                    else
                    {
                        PlayerWork.UsedFieldWazaInArea.Add(wazaNo);
                    }

                    if (player.IsRideBicycle() || usePokemon | player.IsPlayPoketchLoop())
                    {
                        _cutinState = CutInState.WaitLoad;
                    }
                    else
                    {
                        player.PlayPoketchStart();
                        _cutinState = CutInState.PoketchAnimeStart;
                    }
                    break;
                }

                case CutInState.Rotate:
                    if (_fieldObjectRotateYaw.IsBusy)
                        break;

                    player.PlayPoketchStart();
                    _cutinState = CutInState.PoketchAnimeStart;
                    break;

                case CutInState.PoketchAnimeStart:
                    if (!player.GetAnimationPlayer().IsPlayingEnd)
                        break;

                    player.PlayPoketchLoop();
                    _cutinState = CutInState.WaitLoad;
                    break;

                case CutInState.WaitLoad:
                    if (!cutIn.IsLoaded)
                        break;

                    cutIn.PokemonVisibleTimeOffset = wazaNo == WazaNo.SORAWOTOBU ? -0.3f : 0.0f;
                    cutIn.Play();
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_WAZA_CUTIN, null);
                    _cutinState = wazaNo == WazaNo.SORAWOTOBU ? CutInState.Sorawotobu_WaitPlayEffect : CutInState.WaitCutIn;
                    break;

                case CutInState.WaitCutIn:
                {
                    if (cutIn.IsBusy)
                        break;

                    bool isRide = player.IsRideBicycle();
                    if (wazaNo != WazaNo.SORAWOTOBU && !isRide && GetHidenWazaMonsNo(wazaNo) != MonsNo.NULL)
                    {
                        player.PlayPoketchEnd();
                        _cutinState = CutInState.PoketchAnimeEnd;
                    }
                    else
                    {
                        _cutinState = CutInState.End;
                    }
                    break;
                }

                case CutInState.Sorawotobu_WaitPlayEffect:
                    if (!cutIn.IsPlayedEffect)
                        break;

                    _fieldFloatMove.SetValue(0.0f);
                    _fieldFloatMove.MoveTime(1.0f, 1.4f);
                    _cutinState = CutInState.Sorawotobu_WaitPreCaptureInvisible;
                    break;

                case CutInState.Sorawotobu_WaitPreCaptureInvisible:
                    if (_fieldFloatMove.IsBusy)
                        break;

                    cutIn.ForceCaptureInvisible();
                    if (player.IsRideBicycle())
                    {
                        player.yawAngle = 0.0f;
                        player.SetNormalForm(null);
                    }
                    _fieldFloatMove.SetValue(0.0f);
                    _fieldFloatMove.MoveTime(1.0f, 0.72f);
                    _cutinState = CutInState.Sorawotobu_WaitNextCommand;
                    break;

                case CutInState.Sorawotobu_WaitNextCommand:
                    if (_fieldFloatMove.IsBusy)
                        break;

                    _cutinState = CutInState.End;
                    break;

                case CutInState.PoketchAnimeEnd:
                    if (!player.GetAnimationPlayer().IsPlayingEnd)
                        break;

                    player.PlayIdle();
                    _cutinState = CutInState.End;
                    break;
            }
            return _cutinState == CutInState.End;
        }
		private global::Pml.MonsNo GetHidenWazaMonsNo(global::Pml.WazaNo wazaNo) {
            switch (wazaNo)
            {
                case WazaNo.IAIGIRI:
                    return MonsNo.BIPPA;
                case WazaNo.SORAWOTOBU:
                    return MonsNo.MUKUHOOKU;
                case WazaNo.NAMINORI:
                    return MonsNo.BIIDARU;
                case WazaNo.KAIRIKI:
                    return MonsNo.BIIDARU;
                case WazaNo.TAKINOBORI:
                    return MonsNo.BIIDARU;
                case WazaNo.IWAKUDAKI:
                    return MonsNo.BIPPA;
                case WazaNo.ROKKUKURAIMU:
                    return MonsNo.BIIDARU;
                case WazaNo.KIRIBARAI:
                    return MonsNo.MUKUHOOKU;
                default:
                    return MonsNo.NULL;
            }
        }
		private bool CheckHidenWazaForceResetForm(global::Pml.WazaNo wazaNo) {
            if (wazaNo == WazaNo.ROKKUKURAIMU || wazaNo == WazaNo.SORAWOTOBU)
                return EntityManager.activeFieldPlayer.IsRideBicycle();

            return wazaNo == WazaNo.NAMINORI;
        }
