		private bool EvCmdBirthMonthInput() {
            if (_softwareKeyboardSubState != 0)
                return false;

            _softwareKeyboardSubState = 1;
            string headerText = SoftwareKeyboard.GetMessageText("SS_strinput_021");
            SoftwareKeyboard.Param param = new SoftwareKeyboard.Param();
            param.keyboardMode = (SoftwareKeyboard.KeyboardMode)1;
            param.text = "";
            param.textMaxLength = 2;
            param.textMinLength = 1;
            param.headerText = headerText;
            param.subText = null;
            param.guideText = null;
            param.okText = null;
            SoftwareKeyboard.Open(param, (resultText, errorState) =>
            {
                var (isValid, errorMsg) = SoftwareKeyboard.InputCheck(resultText, errorState);
                if (!isValid)
                    return (false, errorMsg);

                int month = 0;
                if (int.TryParse(resultText, out month) && month >= 1 && month <= 12)
                    return (true, null);

                return (false, SoftwareKeyboard.GetMessageText("SS_strinput_037"));
            }, (isSuccess, resultText) =>
            {
                int month = 0;
                if (isSuccess)
                    int.TryParse(resultText, out month);

                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, isSuccess ? month : 0);
                _softwareKeyboardSubState = 0;
            });
            return _softwareKeyboardSubState == 0;
        }
		private bool EvCmdBirthDayInput() {
            int month;
            if (_softwareKeyboardSubState != 0)
                return false;

            _softwareKeyboardSubState = 1;
            month = GetArgInt(_evArg[1]);
            string headerText = SoftwareKeyboard.GetMessageText("SS_strinput_022");
            SoftwareKeyboard.Param param = new SoftwareKeyboard.Param();
            param.keyboardMode = (SoftwareKeyboard.KeyboardMode)1;
            param.text = "";
            param.textMaxLength = 2;
            param.textMinLength = 1;
            param.headerText = headerText;
            param.subText = null;
            param.guideText = null;
            param.okText = null;
            SoftwareKeyboard.Open(param, (resultText, errorState) =>
            {
                var (isValid, errorMsg) = SoftwareKeyboard.InputCheck(resultText, errorState);
                if (!isValid)
                    return (false, errorMsg);

                int dayNum = DayNumInMonth(month);
                int day = 0;
                if (int.TryParse(resultText, out day) && day >= 1 && day <= dayNum)
                    return (true, null);

                string messageLabel;
                switch (dayNum)
                {
                    case 29:
                        messageLabel = "SS_strinput_040";
                        break;
                    case 30:
                        messageLabel = "SS_strinput_039";
                        break;
                    case 31:
                        messageLabel = "SS_strinput_038";
                        break;
                    default:
                        messageLabel = null;
                        break;
                }
                return (false, SoftwareKeyboard.GetMessageText(messageLabel));
            }, (isSuccess, resultText) =>
            {
                int day = 0;
                if (isSuccess)
                    int.TryParse(resultText, out day);

                SetWork(_evArg[1].data, isSuccess ? day : 0);
                _softwareKeyboardSubState = 0;
            });
            return _softwareKeyboardSubState == 0;
        }
		private int DayNumInMonth(int month) {
            int[][] monthTable = new int[3][]
            {
                new int[] { 1, 3, 5, 7, 8, 10, 12 },
                new int[] { 4, 6, 9, 11 },
                new int[] { 2 },
            };
            int[] dayNumTable = new int[] { 31, 30, 29 };
            for (int i = 0; i < monthTable.Length; i++)
            {
                for (int j = 0; j < monthTable[i].Length; j++)
                {
                    if (monthTable[i][j] == month)
                        return dayNumTable[i];
                }
            }
            return dayNumTable[0];
        }
