		private bool EvCmdUnionProc() {
            int connectType = GetArgInt(_evArg[1]);
            int isGroup = GetArgInt(_evArg[2]);
            MatchingParam matchingParam = new MatchingParam();
            UnionRoomManager unionRoomManager = new GameObject("UnionRoomManager").AddComponent<UnionRoomManager>();
            ZoneID zoneId = PlayerWork.zoneID;
            unionRoomManager.SetZoneData(zoneId, PlayerWork.locatorIndex, PlayerWork.playerStatus.grid);
            FlagWork.SetWork(EvWork.WORK_INDEX.UNION_TEMP0, (int)zoneId);

            Dpr.NetworkUtils.MatchingType matchingType;
            if (isGroup == 1)
            {
                matchingParam.password = PlayerWork.RandomGroup.group[1].group_name;
                matchingType = Dpr.NetworkUtils.MatchingType.Group;
            }
            else
            {
                matchingType = matchingPassword.Length > 0 ? Dpr.NetworkUtils.MatchingType.Password : Dpr.NetworkUtils.MatchingType.Random;
                matchingParam.password = matchingPassword.ToString();
            }

            if (connectType == 0)
            {
                matchingParam.GameModeID = Dpr.NetworkUtils.NetworkHelper.CreateUnionGameMode(matchingType, INL1.IlcaNetSessionNetworkType.Local);
                matchingParam.netType = INL1.IlcaNetSessionNetworkType.Local;
                matchingParam.SessionMaxPlayerCount = UnionWork.COMMUNITY_MAX_PLAYER_NUM;
                matchingParam.startMode = INL1.IlcaNetSessionGamingStartMode.Natural;
                unionRoomManager.SetMatchingParam(matchingParam);
                PlayerWork.SetTransitionZone(ZoneID.UNION01, 0);
            }
            else
            {
                matchingParam.GameModeID = Dpr.NetworkUtils.NetworkHelper.CreateUnionGameMode(matchingType, INL1.IlcaNetSessionNetworkType.Internet);
                matchingParam.netType = INL1.IlcaNetSessionNetworkType.Internet;
                matchingParam.SessionMaxPlayerCount = UnionWork.GLOBAL_MAX_PLAYER_NUM;
                matchingParam.startMode = INL1.IlcaNetSessionGamingStartMode.Natural;
                unionRoomManager.SetMatchingParam(matchingParam);
                PlayerWork.SetTransitionZone(ZoneID.UNION02, 0);
            }

            matchingPassword.Clear();
            return true;
        }
