		private bool EvCmdSeedSetWater() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            switch (_kinomiSequence)
            {
                case 0:
                    if (player.IsRideBicycle())
                    {
                        _kinomiSequence = 10;
                        _rideBicycleReserve = true;
                        player.SetNormalForm(() => _kinomiSequence = 0);
                        break;
                    }

                    player.PlayWatering();
                    _kinomiSequence++;
                    break;

                case 1:
                    if (player.GetAnimationPlayer().IsPlayingEnd)
                    {
                        player.PlayWateringLoop();
                        FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CHARA_CAN_WATER, player.GetPodEffectAttachTransform(), eff => _kinomiEffect = eff, null);
                        _kinomiSequence++;
                    }
                    break;

                case 2:
                    if (player.GetAnimationPlayer().currentPlayingTime >= 0.5f)
                    {
                        int groupId = GetCurrentKinomiGrowId();
                        foreach (FieldKinomiGrowEntity growEntity in _FieldKinomiGrowEntity)
                        {
                            if (growEntity == null)
                                continue;

                            if (growEntity.GetPlaceData().GroupId != groupId)
                                continue;

                            KinomiWork.GiveWater(growEntity.KinomiPlaceIndex);
                            growEntity.UpdateStatus();
                        }

                        _kinomiSequence++;
                    }
                    break;

                case 3:
                    player.GetInputVectorIgnoreUpdateInputAngle(out Vector2 stickL, out float stickPowerSq, _deltatime, out bool analogstick);
                    if (stickPowerSq > 0.0f || FieldInput.PushB())
                    {
                        _kinomiSequenceTime = player.GetAnimationPlayer().currentPlayingTime;
                        _kinomiSequence++;
                    }
                    break;

                case 4:
                    {
                        float length = player.GetAnimationPlayer().currentPlayable.GetAnimationClip().length;
                        float time = Mathf.Repeat(player.GetAnimationPlayer().currentPlayingTime, length);
                        if (time <= Mathf.Repeat(_kinomiSequenceTime, length))
                        {
                            if (_kinomiEffect != null)
                            {
                                _kinomiEffect.Stop(0.0f, false);
                                _kinomiEffect = null;
                            }

                            player.PlayWateringEnd();
                            _kinomiSequence++;
                        }
                        else
                        {
                            _kinomiSequenceTime = player.GetAnimationPlayer().currentPlayingTime;
                        }
                    }
                    break;

                case 5:
                    if (player.GetAnimationPlayer().IsPlayingEnd)
                    {
                        if (_rideBicycleReserve)
                        {
                            _rideBicycleReserve = false;
                            _hidenSequence = 10;
                            player.SetRideBicycle(() => _hidenSequence = -1);
                            FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CYCLE_RIDE, player.transform, null, null);
                        }
                        else
                        {
                            player.PlayIdle();
                            _kinomiSequence = -1;
                        }
                    }
                    break;
            }

            return _kinomiSequence < 0;
        }
