		private bool EvCmdPushWaterGymButton() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            FieldNomoseGymSwitchEntity switchEntity = _nomoseGymSwitchEntity;
            if (player == null || switchEntity == null)
                return true;

            if (EntityManager.fieldNomoseGymWater.Length == 0)
                return true;

            if (EntityManager.fieldNomoseGymSwitches.Length == 0)
                return true;

            FieldNomoseGymWaterEntity waterEntity = EntityManager.fieldNomoseGymWater[0];
            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_waterSequence)
            {
                case 0:
                    {
                        float walkSpeed = DataManager.FieldCommonParam[(int)ParamIndx.WalkSpd].param;
                        player.PlayWalk();
                        _fieldObjectMove.SetObjectEntity(player);
                        Vector3 targetPos = switchEntity.worldPosition;
                        targetPos.x += -switchEntity.offset.x - switchEntity.size.x * 0.5f;
                        targetPos.z += switchEntity.offset.y - switchEntity.size.y * 0.5f;
                        targetPos.y = player.worldPosition.y;
                        _fieldObjectMove.MoveSpeed(targetPos, walkSpeed);
                        _fieldObjectRotateYaw.SetObjectEntity(player);
                        Vector3 diff = targetPos - player.worldPosition;
                        _fieldObjectRotateYaw.MoveTime((float)Math.Atan2(diff.x, diff.z) * Mathf.Rad2Deg, 0.1f);
                        _waterSequence++;
                    }
                    break;

                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    if (_fieldObjectRotateYaw.IsBusy)
                        break;

                    player.GetAnimationPlayer().Play(0, 0.0f, 0.0f);
                    {
                        int waterLevel = switchEntity.WaterLevel;
                        foreach (FieldNomoseGymSwitchEntity entity in EntityManager.fieldNomoseGymSwitches)
                            entity.ChangeState(waterLevel);
                    }
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI106, null);
                    _waterSequence++;
                    break;

                case 2:
                    if (switchEntity.HeightMove.IsBusy)
                        break;

                    waterEntity.MoveHeight(switchEntity.WaterLevel);
                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI107, null);
                    _waterSequence++;
                    break;

                case 3:
                    if (waterEntity.IsBusy())
                        break;

                    _waterSequence = -1;
                    break;
            }

            return _waterSequence < 0;
        }
