		private bool EvCmdRotElecGymGear() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            if (player == null)
                return true;

            FieldNagisaGymGearEntity gearEntity = _nagisaGymGearEntity;
            if (gearEntity == null)
                return true;

            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_gearSequence)
            {
                case 0:
                    {
                        float walkSpeed = DataManager.FieldCommonParam[(int)ParamIndx.WalkSpd].param;
                        player.PlayWalk();
                        _fieldObjectMove.SetObjectEntity(player);
                        Vector3 targetPos = gearEntity.worldPosition;
                        targetPos.x += -gearEntity.offset.x - gearEntity.size.x * 0.5f;
                        targetPos.z += gearEntity.offset.y - gearEntity.size.y * 0.5f;
                        targetPos.y = player.worldPosition.y;
                        _fieldObjectMove.MoveSpeed(targetPos, walkSpeed);
                        _fieldObjectRotateYaw.SetObjectEntity(player);
                        Vector3 diff = targetPos - player.worldPosition;
                        _fieldObjectRotateYaw.MoveTime((float)Math.Atan2(diff.x, diff.z) * Mathf.Rad2Deg, 0.1f);
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI106, null);
                        _gearSequence++;
                    }
                    break;

                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    if (_fieldObjectRotateYaw.IsBusy)
                        break;

                    player.GetAnimationPlayer().Play(0, 0.0f, 0.0f);
                    foreach (FieldNagisaGymGearEntity entity in EntityManager.fieldNagisaGymGears)
                        entity.Rotate(gearEntity.GearRotateButton, gearEntity.GearGroupNo);

                    AudioManager.Instance.PlaySe(AK.EVENTS.S_FI113, null);
                    _gearSequence++;
                    break;

                case 2:
                    if (gearEntity.IsRotating())
                        break;

                    {
                        float deg = FieldNagisaGymGearEntity.GetDegRotateType(gearEntity.GearRotateButton);
                        if (gearEntity.GearGroupNo != 0)
                            deg = -deg;

                        int rotate = (int)(deg + GimmickWork.GetGearRotate(_areaID));
                        if (rotate > 360)
                            rotate -= 360;
                        else if (rotate < -360)
                            rotate += 360;

                        GimmickWork.SetGearRotate(_areaID, rotate);
                    }
                    _gearSequence = -1;
                    break;
            }

            return _gearSequence < 0;
        }
