		private global::System.DayOfWeek GetShopUgWeek() {
            int week = FlagWork.GetWork(EvWork.WORK_INDEX.WK_UGSHOP_WEEK);
            if (week <= 0)
            {
                week = FlagWork.GetWork(EvWork.WORK_INDEX.USE_COMMAND_TIME) / 100000000;
                FlagWork.SetWork(EvWork.WORK_INDEX.WK_UGSHOP_WEEK, week);
            }

            return (DayOfWeek)(week - 1);
        }
