		private bool EvCmdTamagoDemo() {
            if (_effSeq == 0)
            {
                PokeParty party = PlayerWork.playerParty;
                int memberCount = (int)party.GetMemberCount();
                for (int i = 0; i < memberCount; i++)
                {
                    PokemonParam param = party.GetMemberPointer((uint)i);
                    if (!param.IsEgg(EggCheckType.ONLY_LEGAL_EGG))
                        continue;
                    if (param.GetOriginalFriendship() != 0)
                        continue;

                    param.Birth();
                    poketool.poke_memo.poketool_poke_memo.SetFromEggBirth(param, PlayerWork.playerStatus, PlayerWork.zoneID);
                    TvWork.EggHatch(param, (int)PlayerWork.zoneID);
                    FieldPoketch.AddPokemonHistory(param);
                    FieldPoketch.HidePoketch(false);
                    FlagWork.SetSysFlag(EvWork.SYSFLAG_INDEX.SYS_INPUT_OFF, true);
                    var demo = new Dpr.Demo.Demo_Hatch(param);
                    demo.OnEndDemo = () =>
                    {
                        RecordWork.Add(RECORD_ID.RECID_TAMAGO_HATCHING, 1);
                        _effSeq = -1;
                        if (CheckPartyEggHatchingCount() >= 1)
                        {
                            _eventEndDelegate = () =>
                            {
                                EntityManager.activeFieldPlayer.StopCrossInputAndBicycle();
                                EggHatchingEvent();
                            };
                        }
                        else
                        {
                            FlagWork.SetSysFlag(EvWork.SYSFLAG_INDEX.SYS_INPUT_OFF, false);
                        }
                    };
                    PlayReportManager.SaveReportLog_PokemonId((uint)param.GetMonsNo(), param.GetFormNo(), 1, param.IsRare() ? 1u : 0u);
                    FieldCanvas.PlayDemoOrStock(demo);
                    _effSeq = 1;
                    break;
                }
            }

            return _effSeq < 0;
        }
