		private bool EvCmdOokisaRecordChk() {
            PokemonParam param = GetPokemonParam(GetArgInt(_evArg[3]), GetArgInt(_evArg[2]));
            MonsNo monsNo = param.GetMonsNo();
            float size = CalcPokemonSize(monsNo, CalcPokemonSizeValue(param));
            float recordSize = CalcPokemonSize(monsNo, FlagWork.GetWork(EvWork.WORK_INDEX.SYS_WORK_OOKISA_RECORD));
            int result;
            if (recordSize < size)
                result = 2;
            else if (recordSize == size)
                result = 1;
            else
                result = 0;

            SetWork(_evArg[1].data, result);
            return true;
        }
		private int CalcPokemonSizeValue(global::Pml.PokePara.PokemonParam param) {
            uint hp = param.GetNativeTalentPower(PowerID.HP) & 0xF;
            uint atk = param.GetNativeTalentPower(PowerID.ATK);
            uint def = param.GetNativeTalentPower(PowerID.DEF);
            uint agi = param.GetNativeTalentPower(PowerID.AGI) & 0xF;
            uint spatk = param.GetNativeTalentPower(PowerID.SPATK);
            uint spdef = param.GetNativeTalentPower(PowerID.SPDEF);
            uint rndLow = param.GetPersonalRnd() & 0xFF;
            uint rndHigh = (param.GetPersonalRnd() >> 8) & 0xFF;
            uint high = rndLow ^ (((atk ^ def) & 0xF) * hp);
            uint low = rndHigh ^ (((spatk ^ spdef) & 0xF) * agi);
            return (int)((high << 8) | low);
        }
		private float CalcPokemonSize(global::Pml.MonsNo monsNo, int sizeValue) {
            int index = PokemonSizeTable.Length - 1;
            int last = index;
            for (int i = 0; i < last - 1; i++)
            {
                if (PokemonSizeTable[i + 1].Item3 > sizeValue)
                {
                    index = i;
                    break;
                }
            }

            var table = PokemonSizeTable[index];
            // The binary divides unguarded (sdiv @02c7af7c): ARM64 yields 0 for a zero divisor where C# would throw.
            int divisor = table.Item2;
            int scale = (divisor != 0 ? (sizeValue - table.Item3) / divisor : 0) + table.Item1;
            return (float)Pml.Personal.PersonalSystem.GetPersonalData(monsNo, 0).height / 100.0f * scale / 10.0f;
        }
