		private bool EvCmdKasekiItemNo() {
            int index = GetArgInt(_evArg[3]);
            int count = 0;
            int itemNo = 0;
            int position = 0;
            foreach (int key in KasekiFukugenTable.Keys)
            {
                Dpr.Item.ItemInfo itemInfo = ItemWork.GetItemInfo(key);
                if (itemInfo != null)
                    count += itemInfo.count;

                if (index <= count)
                {
                    itemNo = key;
                    break;
                }

                position++;
            }

            if (itemNo == 0)
                position = 0;

            SetWork(_evArg[1].data, itemNo);
            SetWork(_evArg[2].data, position);
            return true;
        }
