		private bool EvCmdBTowerAppSetProc() {
            int isSingle = GetArgInt(_evArg[1]);
            int isNormal = GetArgInt(_evArg[2]);
            _isOpenBtlTowerRecode = true;
            var window = UIManager.Instance.CreateUIWindow<BattleTowerRecordWindow>(UIWindowID.BATTLETOWER_RECORD);
            window.onClosed = w => _isOpenBtlTowerRecode = false;
            var param = new BattleTowerRecordWindow.Param();
            param.isSuspended = false;
            if (isSingle == 1)
                param.recordType = isNormal == 1 ? BattleTowerRecordWindow.Param.RecordType.Single : BattleTowerRecordWindow.Param.RecordType.MasterSingle;
            else
                param.recordType = isNormal == 1 ? BattleTowerRecordWindow.Param.RecordType.Double : BattleTowerRecordWindow.Param.RecordType.MasterDouble;

            param.isSuspended = BtlTowerWork.GetRenshou((int)param.recordType) != 0;
            switch (param.recordType)
            {
                case BattleTowerRecordWindow.Param.RecordType.Single:
                    param.consecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_SINGLE_NOW);
                    param.maxConsecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_SINGLE);
                    break;
                case BattleTowerRecordWindow.Param.RecordType.Double:
                    param.consecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_DOUBLE_NOW);
                    param.maxConsecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_DOUBLE);
                    break;
                case BattleTowerRecordWindow.Param.RecordType.MasterSingle:
                    param.consecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_MASTER_SINGLE_NOW);
                    param.maxConsecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_MASTER_SINGLE);
                    param.rank = BtlTowerWork.GetRank(2);
                    break;
                case BattleTowerRecordWindow.Param.RecordType.MasterDouble:
                    param.consecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_MASTER_DOUBLE_NOW);
                    param.maxConsecutiveWins = (int)RecordWork.Get(RECORD_ID.RECID_RENSHOU_MASTER_DOUBLE);
                    param.rank = BtlTowerWork.GetRank(3);
                    break;
            }

            window.Open(param, UIWindow.WINDOWID_FIELD);
            return true;
        }
