		private bool EvCmdMoveSafariTrain() {
            int posIndex = GetArgInt(_evArg[1]);
            int rideType = GetArgInt(_evArg[2]);
            FieldEventTrainEntity train = GetTrain();
            if (train == null)
                return true;

            switch (_trainSequence)
            {
                case 0:
                    train.Move(posIndex, rideType == 4);
                    _trainSequence = 1;
                    break;
                case 1:
                    if (!train.IsBusy)
                        _trainSequence = -1;
                    break;
            }

            return _trainSequence < 0;
        }
