            if (!EncountDataWork.IsMovePokeData_ReActive(index))
                return true;

            MonsNo monsNo = index == 1 ? MonsNo.KURESERIA : MonsNo.EMURITTO;
            // The binary calls GetRandom and never uses the result (@02c7e350).
            RandomGroupWork.GetRandom(RANDOMGROUP.RANDOMGROUP_MINE);
            PokeParty party = EncountTools.CreateSimpleParty(monsNo, 50, talentVNum: 3);
            PokemonParam param = party.GetMemberPointer(0);
            EncountDataWork.SetMovePokeData_Status(index, EncountDataWork.GetPokeStatus.Active);
            EncountDataWork.SetMovePokeData(param, true);
            EncountDataWork.MovePoke_RandomZone(monsNo);
            return true;
        }
