		private bool EvCmdKujiAtariChk() {
            int maxDigits = 0;
            int pokeno = 0;
            int pokemonIndex = 0;
            int tray = -1;
            PokeParty party = PlayerWork.playerParty;
            int memberCount = (int)party.GetMemberCount();
            for (int i = 0; i < memberCount; i++)
            {
                PokemonParam param = party.GetMemberPointer((uint)i);
                int digits = FieldLotteryWork.CheckPokemon(param);
                if (maxDigits < digits)
                {
                    maxDigits = digits;
                    pokeno = (int)param.GetMonsNo();
                    pokemonIndex = i;
                    tray = -1;
                }
            }

            BoxScan((param, trayIndex, pos) =>
            {
                int digits = FieldLotteryWork.CheckPokemon(param);
                if (maxDigits < digits)
                {
                    maxDigits = digits;
                    pokeno = (int)param.GetMonsNo();
                    pokemonIndex = pos;
                    tray = trayIndex;
                }

                return true;
            });

            SetWork(_evArg[1].data, pokeno);
            SetWork(_evArg[2].data, maxDigits);
            SetWork(_evArg[3].data, tray);
            SetWork(_evArg[4].data, pokemonIndex);
            SetWork(_evArg[5].data, FieldLotteryWork.GetWinningNumber());
            return true;
        }
