		private bool EvCmdTVStart() {
            TV_PROGRAM program = TvWork.FindEnableProgram();
            if (program == TV_PROGRAM.MAX)
            {
                if (TvCommercials == null || TvCommercialsCurrentIndex >= TvCommercials.Length)
                {
                    TvCommercials = TvWork.GetCommercialIndexArray();
                    TvCommercialsCurrentIndex = 0;
                }

                TvDataTable.Sheetdata data = TvWork.GetTableData(TvCommercials[TvCommercialsCurrentIndex++]);
                if (data != null)
                    PlayTv(data);
            }
            else
            {
                TvDataTable.Sheetdata data = TvWork.GetTableData(program);
                if (data != null)
                    PlayTv(data);
            }

            return true;
        }
		private void PlayTv(global::XLSXContent.TvDataTable.Sheetdata data) {
            _currentTvProgram = data.Channel != 0 ? (TV_PROGRAM)data.TpicID : TV_PROGRAM.MAX;
            FieldTvEntity tvEntity = FindTvEntity();
            if (tvEntity != null)
                tvEntity.SetView(data.SetCRT);

            JumpLabel(data.ReadScript, () => JumpLabel("ev_tv_end", null));
        }
		private global::FieldTvEntity FindTvEntity() {
            Vector3 playerPos = EntityManager.activeFieldPlayer.worldPosition;
            FieldTvEntity result = null;
            float minDistance = 100000.0f;
            foreach (FieldTvEntity tvEntity in EntityManager.fieldTv)
            {
                float distance = Vector3.Distance(playerPos, tvEntity.worldPosition);
                if (distance < minDistance)
                {
                    minDistance = distance;
                    result = tvEntity;
                }
            }

            return result;
        }
		private bool EvCmdTVEnd() {
            FieldTvEntity tvEntity = FindTvEntity();
