            if (_currentTvProgram != TV_PROGRAM.MAX)
            {
                TvWork.AddTvWatchCount();
                TvWork.TVTpicDisable(_currentTvProgram);
                _currentTvProgram = TV_PROGRAM.MAX;
            }

            return true;
        }
