		private global::System.Collections.IEnumerator OpOpenSubContentsWindow<T>(global::UIWindowID windowID, global::System.Action<T> onCompletedLoad) where T : global::Dpr.UI.UIWindow {
            while (MsgWindowManager.IsOpenWindow)
                yield return null;

            var windows = new List<UIWindowID> { windowID };
            var uiManager = SmartPoint.AssetAssistant.SingletonMonoBehaviour<UIManager>.Instance;
            yield return uiManager.OpLoadWindows(windows, true);

            var window = uiManager.CreateUIWindow<T>(windowID);
            window.onClosed = _ =>
            {
                _isOpenSubContentsMenu = false;
                uiManager.UnloadWindows(windows, false);
            };
            onCompletedLoad?.Invoke(window);
        }
