		private bool EvCmdMoveFldLift() {
            FieldEventLiftEntity lift = _runEventLiftEntity;
            if (lift == null)
                return true;

            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_liftSequence)
            {
                case 0:
                    {
                        float walkSpeed = DataManager.FieldCommonParam[(int)ParamIndx.WalkSpd].param;
                        FieldPlayerEntity player = EntityManager.activeFieldPlayer;
                        player.PlayWalk();
                        _fieldObjectMove.SetObjectEntity(player);
                        Vector3 targetPos = lift.worldPosition;
                        targetPos.x += -lift.offset.x - lift.size.x * 0.5f;
                        targetPos.z += lift.offset.y - lift.size.y * 0.5f;
                        _fieldObjectMove.MoveSpeed(targetPos, walkSpeed);
                        _fieldObjectRotateYaw.SetObjectEntity(player);
                        Vector3 diff = targetPos - player.worldPosition;
                        _fieldObjectRotateYaw.MoveTime((float)Math.Atan2(diff.x, diff.z) * Mathf.Rad2Deg, 0.1f);
                        _liftSequence++;
                    }
                    break;

                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;

                    {
                        bool isPlus = (lift.LiftWorldValueA < lift.LiftWorldValueB) ^ lift.IsLiftB;
                        float yawAngle;
                        if (lift.LiftAxis == FieldEventLiftEntity.LiftAxisType.X)
                            yawAngle = isPlus ? 90.0f : -90.0f;
                        else if (lift.LiftAxis == FieldEventLiftEntity.LiftAxisType.Z)
                            yawAngle = isPlus ? 0.0f : 180.0f;
                        else
                            yawAngle = isPlus ? 180.0f : 0.0f;

                        _fieldObjectRotateYaw.MoveTime(yawAngle, 0.2f);
                    }
                    _liftSequence++;
                    break;

                case 2:
                    if (!_fieldObjectRotateYaw.IsBusy)
                    {
                        Vector3 liftOffset;
                        lift.Play(lift.IsLiftB ? 1 : 0);
                        FieldPlayerEntity fieldPlayer = EntityManager.activeFieldPlayer;
                        fieldPlayer.PlayIdle();
                        fieldPlayer.isLanding = false;
                        liftOffset = fieldPlayer.worldPosition - lift.worldPosition;
                        EntityManager.activeFieldPlayer.LateUpdateEvent = player =>
                        {
                            player.worldPosition = lift.transform.position + liftOffset;
                            if (lift.isCompleted)
                            {
                                player.isLanding = true;
                                return true;
                            }

                            return false;
                        };
                        lift.PlayStartSE();
                        _liftSequence++;
                    }
                    break;

                case 3:
                    if (!lift.IsCompleteMoved())
                        break;

                    lift.PlayEndSE();
                    _liftSequence++;
                    break;

                case 4:
                    if (!lift.isCompleted)
                        break;
                    if (EntityManager.activeFieldPlayer.LateUpdateEvent != null)
                        break;

                    lift.IsLiftB = !lift.IsLiftB;
                    if (lift.LiftFlag != EvWork.FLAG_INDEX.FLAG_END_SAVE_SIZE)
                        FlagWork.SetFlag(lift.LiftFlag, lift.IsLiftB);

                    if (lift.MoveAfterWalk)
                    {
                        FieldPlayerEntity player = EntityManager.activeFieldPlayer;
                        player.PlayWalk();
                        Vector3 pos = player.worldPosition;
                        bool isPlus = (lift.LiftWorldValueA < lift.LiftWorldValueB) ^ lift.IsLiftB;
                        int index;
                        float offset;
                        if (lift.LiftAxis != FieldEventLiftEntity.LiftAxisType.X)
                        {
                            index = 2;
                            float half = lift.size.y * 0.5f + 0.5f + 0.25f;
                            offset = ((lift.LiftAxis == FieldEventLiftEntity.LiftAxisType.Z) ^ isPlus) ? half : -half;
                        }
                        else
                        {
                            index = 0;
                            float half = lift.size.x * 0.5f + 0.5f + 0.25f;
                            offset = isPlus ? -half : half;
                        }

                        pos[index] = Mathf.Round(pos[index] + offset);
                        float walkSpeed = DataManager.FieldCommonParam[(int)ParamIndx.WalkSpd].param;
                        _fieldObjectMove.SetObjectEntity(player);
                        _fieldObjectMove.MoveSpeed(pos, walkSpeed);
                    }

                    lift.StopSE();
                    _liftSequence++;
                    break;

                case 5:
                    if (lift.MoveAfterWalk && _fieldObjectMove.IsBusy)
                        break;

                    if (lift.MoveAfterWalk)
                        EntityManager.activeFieldPlayer.PlayIdle();

                    if (lift.IsLiftB && lift.LiftFixB)
                        lift.IsLiftEnable = false;

                    _liftSequence = -1;
                    break;
            }

            return _liftSequence == -1;
        }
