		private bool EvCmd_D20R0106Legend_IsUnseal() {
            int[] legendMonsNos = new int[] { (int)MonsNo.REZIROKKU, (int)MonsNo.REZIAISU, (int)MonsNo.REZISUTIRU };
            HashSet<int> foundMonsNos = new HashSet<int>();
            PokeParty party = PlayerWork.playerParty;
            int memberCount = (int)party.GetMemberCount();
            for (int i = 0; i < memberCount; i++)
            {
                PokemonParam param = party.GetMemberPointer((uint)i);
                if (!CheckValidPokemonParam(param))
                    continue;

                if (Array.IndexOf(legendMonsNos, (int)param.GetMonsNo()) >= 0)
                    foundMonsNos.Add((int)param.GetMonsNo());
            }

            SetWork(_evArg[1].data, foundMonsNos.Count >= legendMonsNos.Length ? 1 : 0);
            return true;
        }
