		private bool EvCmdNameInStone() {
            switch (_softwareKeyboardSubState)
            {
                case 0:
                {
                    _softwareKeyboardSubState = 1;
                    string headerText = SoftwareKeyboard.GetMessageText("SS_strinput_044");
                    SoftwareKeyboard.Param param = new SoftwareKeyboard.Param();
                    param.text = "";
                    param.textMinLength = 1;
                    param.textMaxLength = SoftwareKeyboard.LanguageMaxLength(10);
                    param.headerText = headerText;
                    param.invalidCharFlag = SoftwareKeyboard.InvalidChar.AtMark;
                    SoftwareKeyboard.Open(param, (text, errorState) => SoftwareKeyboard.InputCheck(text, errorState), (isOk, text) =>
                    {
                        if (isOk && text.Length > 0)
                        {
                            string firstName;
                            string secondName;
                            if (text.Length >= 5)
                            {
                                firstName = text.Substring(0, 5);
                                secondName = text.Substring(5);
                            }
                            else
                            {
                                firstName = text;
                                secondName = "";
                            }

                            PlayerWork.tvData.UseRecord.str_data[32].value = firstName;
                            PlayerWork.tvData.MyRecord.str_data[32].value = secondName;
                            SetWork(_evArg[1].data, 1);
                        }
                        else
                        {
                            SetWork(_evArg[1].data, 0);
                        }

                        _softwareKeyboardSubState = 2;
                    });
                    return false;
                }
                case 2:
                    return true;
                default:
                    return false;
            }
        }
