		private bool EvCmdRotomuFormCheck() {
            int GetRotomuFormBitFlag(PokemonParam param)
            {
                if (CheckValidPokemonParam(param) && param.GetMonsNo() == MonsNo.ROTOMU)
                    return 1 << param.GetFormNo();
                return 0;
            }

            int retFlags = 0;
            PokeParty party = PlayerWork.playerParty;
            int count = (int)party.GetMemberCount();
            for (int i = 0; i < count; i++)
                retFlags |= GetRotomuFormBitFlag(party.GetMemberPointer((uint)i));
            retFlags |= GetRotomuFormBitFlag(AzukariyaWork.Get(0));
            retFlags |= GetRotomuFormBitFlag(AzukariyaWork.Get(1));
            BoxScan(param => retFlags |= GetRotomuFormBitFlag(param));
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, (retFlags >> 1) & 1);
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[2].data, (retFlags >> 2) & 1);
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[3].data, (retFlags >> 3) & 1);
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[4].data, (retFlags >> 4) & 1);
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[5].data, (retFlags >> 5) & 1);
            return true;
        }
		private bool EvCmdRotomuFormWazaChange() {
            int pokeIndex = GetArgInt(_evArg[1]);
            int wazaIndex = GetArgInt(_evArg[2]);
            // The third argument is fetched but never used (only its FlagWork.GetWork call survives, 02c861c4).
            int unusedArg = GetArgInt(_evArg[3]);
            int formNo = GetArgInt(_evArg[4]);
            PokemonParam param = GetPokemonParam(-1, pokeIndex);
            if (CheckValidPokemonParam(param) && param.GetMonsNo() == MonsNo.ROTOMU)
            {
                param.ChangeFormNo((ushort)formNo, null);
                param.RemoveAllRotomWaza();
                if (wazaIndex >= 0)
                    param.SetRotomWaza((byte)wazaIndex);
                ZukanWork.SetPoke(param, GET_STATUS.GET);
                FieldManager.fwMng.CheckPartnerPokeChange(param, false);
            }
            return true;
        }
		private bool EvCmdTemotiRotomuFormChangeGet() {
            PokeParty party = PlayerWork.playerParty;
            int num = 0;
            int firstIndex = -1;
            int count = (int)party.GetMemberCount();
            for (int i = 0; i < count; i++)
            {
                PokemonParam param = party.GetMemberPointer((uint)i);
                if (CheckValidPokemonParam(param) && param.GetMonsNo() == MonsNo.ROTOMU && param.GetFormNo() != 0)
                {
                    if (firstIndex < 0)
                        firstIndex = i;
                    num++;
                }
            }
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, num);
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[2].data, firstIndex);
            return true;
        }
		private bool EvCmdTemotiPokeChkNum() {
            bool CheckDuplicate()
            {
                PokeParty dupParty = PlayerWork.playerParty;
                int dupCount = (int)dupParty.GetMemberCount();
                for (int i = 0; i < dupCount; i++)
                {
                    PokemonParam param1 = dupParty.GetMemberPointer((uint)i);
                    if (!CheckValidPokemonParam(param1))
                        continue;
                    for (int j = 0; j < i; j++)
                    {
                        PokemonParam param2 = dupParty.GetMemberPointer((uint)j);
                        if (CheckValidPokemonParam(param2) && param1.GetMonsNo() == param2.GetMonsNo())
                            return true;
                    }
                }
                return false;
            }

            int monsNo = GetArgInt(_evArg[2]);
            int num;
            if (monsNo == 0)
            {
                num = CheckDuplicate() ? 1 : 0;
            }
            else
            {
                PokeParty party = PlayerWork.playerParty;
                num = 0;
                int count = (int)party.GetMemberCount();
                for (int i = 0; i < count; i++)
                {
                    PokemonParam param = party.GetMemberPointer((uint)i);
                    if (CheckValidPokemonParam(param) && (int)param.GetMonsNo() == monsNo)
                        num++;
                }
            }
            FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, num);
            return true;
        }
