		private bool EvCmdNaminoriEnd() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            switch (_hidenSequence)
            {
                case 0:
                    {
                        player.PlayNaminoriEnd();
                        _fieldObjectMove.SetObjectEntity(player);
                        Vector3 targetPos = player.CalcSwimEndTargetPosition();
                        float moveTime = player.GetAnimationPlayer().currentRemaingTime - 0.6f;
                        _fieldObjectMove.MoveTime(targetPos, moveTime);
                        player.DisappearSwimBiidaru((targetPos - player.worldPosition).magnitude, moveTime);
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI005, null);
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI033_END, null);
                        FieldManager.Instance.CallEffect(EffectFieldID.EF_F_WAZA_SURF_OUT, player.BiidaruTransform, new Vector3(0f, 0.5f, 0f), null, null);
                        FieldManager.Instance.SetBgmEvent(FieldManager.Instance.GetMapBgmState());
                        _hidenSequence++;
                    }
                    break;
                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    FieldManager.Instance.CallEffect(EffectFieldID.EF_F_CHARA_LAND_GROUND, player.transform, null, null);
                    _hidenSequence++;
                    break;
                case 2:
                    if (!player.GetAnimationPlayer().IsPlayingEnd)
                        break;
                    player.beadaruVisibility = false;
                    player.ChangeSwim(false);
                    player.PlayIdle(0f);
                    player.isLanding = true;
                    Dpr.Field.SwayGrass.SwayGrass_InitSwayGrass();
                    CreateTurearuki();
                    _hidenSequence = -1;
                    break;
            }
            return _hidenSequence < 0;
        }
		private bool EvCmdTakikudari() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_hidenSequence)
            {
                case 0:
                    {
                        _takiTargetPosition = player.CalcWaterfallDownTargetPosition();
                        Vector3 movePos = _takiTargetPosition;
                        movePos.y = player.worldPosition.y;
                        _fieldObjectMove.SetObjectEntity(player);
                        _fieldObjectMove.MoveTime(movePos, DataManager.FieldCommonParam[(int)ParamIndx.Takikudari_MoveTime].param);
                        _fieldObjectRotateYaw.SetObjectEntity(player);
                        _fieldObjectRotateYaw.MoveTime(player.worldPosition.z < _takiTargetPosition.z ? 0f : 180f, 0.1f);
                        player.ForcePlayNaminoriEffect = true;
                        player.PlayWaterFallDownEffect();
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI036, null);
                        _hidenSequence++;
                    }
                    break;
                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    _fieldObjectMove.MoveTime(_takiTargetPosition, DataManager.FieldCommonParam[(int)ParamIndx.Takikudari_DownTime].param);
                    _hidenSequence++;
                    break;
                case 2:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    _mistPlate.Update(PlayerWork.zoneID);
                    player.ForcePlayNaminoriEffect = false;
                    player.StopSwimEffect();
                    _hidenSequence = -1;
                    break;
            }
            return _hidenSequence == -1;
        }
