		private void TemotiBoxScan(global::System.Func<global::Pml.PokePara.PokemonParam, int, int, bool> action) {
            uint count = PlayerWork.playerParty.GetMemberCount();
            for (uint i = 0; i < count; i++)
            {
                PokemonParam param = PlayerWork.playerParty.GetMemberPointer(i);
                if (param.IsNull())
                    continue;
                if (!action(param, -1, (int)i))
                    return;
            }
            BoxScan((param, trayIndex, index) => action(param, trayIndex, index));
        }
		private void BoxScan(global::System.Action<global::Pml.PokePara.PokemonParam> action) {
            BoxScan((param, tray, index) =>
            {
                action(param);
                return true;
            });
        }
		private void BoxScan(global::System.Func<global::Pml.PokePara.PokemonParam, int, int, bool> action) {
            PokemonParam param = new PokemonParam();
            int trayMax = Dpr.Box.BoxWork.GetTrayMax();
            for (int tray = 0; tray < trayMax; tray++)
            {
                for (int pos = 0; pos < 30; pos++)
                {
                    Dpr.Box.BoxPokemonWork.GetPokemon(param, tray, pos);
                    if (param.IsNull())
                        continue;

                    if (!action(param, tray, pos))
                        return;
                }
            }
        }
