		private global::DIR SetupHeroMoveGridCenterFrontDir(in global::UnityEngine.RectInt stopGridArea, in global::UnityEngine.Vector2Int nowGrid, in global::UnityEngine.Vector2Int oldGrid) {
            // The shipped code touches EntityManager (class init only); the player is never read.
            var player = EntityManager.activeFieldPlayer;

            Vector2Int diff = nowGrid - oldGrid;
            if (diff.x != 0 && diff.y != 0)
            {
                // Diagonal step: keep the axis whose corner cell is still inside the stop area.
                if (InGridArea(stopGridArea, nowGrid.x, oldGrid.y))
                    diff.y = 0;
                else if (InGridArea(stopGridArea, oldGrid.x, nowGrid.y))
                    diff.x = 0;
                else if (stopGridArea.width < stopGridArea.height)
                    diff.y = 0;
                else
                    diff.x = 0;
            }

            if (diff.x != 0)
                return diff.x >= 0 ? DIR.DIR_RIGHT : DIR.DIR_LEFT;

            if (diff.y != 0)
                return diff.y >= 0 ? DIR.DIR_DOWN : DIR.DIR_UP;

            return DIR.DIR_NOT;
        }
		private static bool InGridArea(in global::UnityEngine.RectInt area, int x, int y) {
            return area.x <= x && area.xMax >= x && area.y <= y && area.yMax >= y;
        }
