            if (_hit_object != null && _hit_object.EventParams.IsObject)
            {
                CalcNeckRotateAngle(EntityManager.activeFieldPlayer, ref _hit_position, out angle);
                EntityManager.activeFieldPlayer.NeckAngle = new Vector3(angle, 0f, 0f);
            }
            return true;
        }
		private bool NeckRotateTarget(bool isTurnNotFlag) {
            var character = _hit_object as FieldCharacterEntity;
            if (isTurnNotFlag)
            {
                if (character != null)
                {
                    CalcNeckRotateAngle(character, ref EntityManager.activeFieldPlayer.worldPosition, out float angle);
                    character.NeckAngle = new Vector3(angle, 0.0f, 0.0f);
                }
            }
            else
            {
                if (character != null && character.EventParams.IsObject && CalcNeckRotateAngle(character, ref EntityManager.activeFieldPlayer.worldPosition, out float angle))
                    character.NeckAngle = new Vector3(angle, 0.0f, 0.0f);
                else
                    Turn_HitObjectToHero();
            }

            return true;
        }
		private bool CalcNeckRotateAngle(global::FieldCharacterEntity player, ref global::UnityEngine.Vector3 tPos, out float angle) {
            float yawAngle = player.yawAngle;
            Vector3 position = player.worldPosition;
            Vector3 forward = player.transform.forward; // read and unused in the shipped code
            Vector3 dir = tPos - position;
            dir.Normalize();
            angle = FieldCalc.DiffAngle(yawAngle, Quaternion.LookRotation(dir).eulerAngles.y);
            if (angle <= -45f)
            {
                angle = -45f;
                return false;
            }

            if (angle >= 45f)
            {
                angle = 45f;
                return false;
            }

            return true;
        }
		private bool EvCmdWarpStartAnimation() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            if (player == null)
                return true;
            AnimationPlayer anim = player.GetAnimationPlayer();
            if (anim == null)
                return true;
            int fadeColor = GetArgInt(_evArg[1]);
            _fieldFloatMove.Update(_deltatime);
            if (_warpSpeedSequence <= 2)
            {
                _warpSpeedSequenceTime -= _deltatime;
                if (_warpSpeedSequenceTime <= 0f)
                {
                    switch (_warpSpeedSequence)
                    {
                        case 0:
                            anim.Play(15, 0.1f);
                            _warpSpeedSequenceTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_RotateTime1].param;
                            break;
                        case 1:
                            _warpSpeedSequenceTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_RotateTime2].param;
                            break;
                        case 2:
                            PlaySe("UI_bag_item_ananuke");
                            _warpSpeedSequenceTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_RotateTime3].param;
                            break;
                    }
                    anim.SetAnimSpeed(0.5f / _warpSpeedSequenceTime);
                    _warpSpeedSequence++;
                }
            }
            switch (_warpSequence)
            {
                case 0:
                    {
                        DeleteTurearuki();
                        float cameraDist = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_CameraDist].param - GameManager.fieldCamera.TargetRange;
                        float cameraTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_CameraTime].param;
                        GameManager.fieldCamera.TargetRangeOffset.MoveTime(cameraDist, cameraTime);
                        float fadeWaitTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_FadeWaitTime].param;
                        _fieldFloatMove.SetValue(0f);
                        _fieldFloatMove.MoveTime(1f, fadeWaitTime);
                        _warpSequence++;
                    }
                    break;
                case 1:
                    {
                        if (_fieldFloatMove.IsBusy)
                            break;
                        Fader.fillColor = fadeColor == 1 ? Color.white : Color.black;
                        float fadeTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_FadeTime].param;
                        Fader.FadeOut(fadeTime);
                        _fieldFloatMove.MoveTime(1f, fadeTime);
                        _warpSequence++;
                    }
                    break;
                case 2:
                    if (_fieldFloatMove.IsBusy)
                        break;
                    _callLabel_SceneChange = "ev_exec_warp_end";
                    _warpSequence = -1;
                    break;
            }
            return _warpSequence < 0;
        }
		private bool EvCmdWarpEndAnimation() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            if (player == null)
                return true;
            AnimationPlayer anim = player.GetAnimationPlayer();
            if (anim == null)
                return true;
            _fieldFloatMove.Update(_deltatime);
            if (_warpSpeedSequence <= 3)
            {
                _warpSpeedSequenceTime -= _deltatime;
                if (_warpSpeedSequenceTime <= 0f)
                {
                    float rotateTime = 0f;
                    switch (_warpSpeedSequence)
                    {
                        case 0:
                            anim.Play(15, 0.1f);
                            rotateTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_RotateTime1].param;
                            _warpSpeedSequenceTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_CameraTime].param - DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_RotateTime2].param - DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_RotateTime3].param;
                            break;
                        case 1:
                            rotateTime = _warpSpeedSequenceTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_RotateTime2].param;
                            break;
                        case 2:
                            rotateTime = _warpSpeedSequenceTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_RotateTime3].param;
                            break;
                        case 3:
                            anim.SetAnimSpeed(0f);
                            anim.Play(0, 0.1f);
                            anim.SetAnimSpeed(1f);
                            break;
                    }
                    // Shipped: case 3 (and any out-of-range step) ends with SetAnimSpeed(0.5f / 0f) (02c8bbe8).
                    anim.SetAnimSpeed(0.5f / rotateTime);
                    _warpSpeedSequence++;
                }
            }
            switch (_warpSequence)
            {
                case 0:
                    {
                        float cameraDist = DataManager.FieldCommonParam[(int)ParamIndx.WarpStart_CameraDist].param - GameManager.fieldCamera.TargetRange;
                        GameManager.fieldCamera.TargetRangeOffset.SetValue(cameraDist);
                        _warpSequence++;
                    }
                    break;
                case 1:
                    {
                        float cameraTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_CameraTime].param;
                        GameManager.fieldCamera.TargetRangeOffset.MoveTime(0f, cameraTime);
                        float fadeTime = DataManager.FieldCommonParam[(int)ParamIndx.WarpEnd_FadeTime].param;
                        _fieldFloatMove.SetValue(0f);
                        _fieldFloatMove.MoveTime(1f, Mathf.Max(fadeTime, cameraTime));
                        Fader.FadeIn(fadeTime);
                        _warpSequence++;
                    }
                    break;
                case 2:
                    if (_fieldFloatMove.IsBusy)
                        break;
                    if (_warpSpeedSequence < 3)
                        break;
                    _warpSequence = -1;
                    break;
            }
            return _warpSequence < 0;
        }
		private bool EvCmdSafariScopeSequence() {
            MonsNo monsNo;
            ushort formNo;
            _fieldFloatMove.Update(_deltatime);
            switch (_scopeSequence)
            {
                case 0:
                    {
                        Fader.FadeIn(_fadeSpeed);
                        float waitTime = _fadeSpeed + DataManager.FieldCommonParam[(int)ParamIndx.SafariScope_WaitTime].param;
                        _fieldFloatMove.SetValue(0f);
                        _fieldFloatMove.MoveTime(1f, waitTime);
                        _scopeSequence++;
                    }
                    break;
                case 1:
                    {
                        if (_fieldFloatMove.IsBusy)
                            break;
                        Telescope.GetCurrentMons(out monsNo, out formNo);
                        Dpr.Demo.Demo_PokeViewer demo = new Dpr.Demo.Demo_PokeViewer(monsNo, formNo, Sex.NUM);
                        demo.OnEndDemo = () => _scopeSequence++;
                        FieldCanvas.PlayDemoOrStock(demo);
                        _scopeSequence++;
                    }
                    break;
                case 2:
                    break;
                case 3:
                    Fader.FadeOut(_fadeSpeed);
                    _fieldFloatMove.MoveTime(1f, _fadeSpeed);
                    _scopeSequence++;
                    break;
                case 4:
                    if (_fieldFloatMove.IsBusy)
                        break;
                    foreach (SmartPoint.Rendering.PostProcessFilter filter in GameManager.fieldCamera.GetComponentsInChildren<SmartPoint.Rendering.PostProcessFilter>())
                        filter.Reset();
                    Telescope.JumpNext();
                    _scopeSequence = -1;
                    break;
            }
            return _scopeSequence < 0;
        }
