		private bool EvCmdAzukariyaStoreUI() {
            if (_azukariyaSequence == 0)
            {
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, 0);
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[2].data, -1);
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[3].data, -1);
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[4].data, -1);
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[5].data, -1);
                BoxWindow boxWindow = UIManager.Instance.CreateUIWindow<BoxWindow>(UIWindowID.BOX);
                boxWindow.onClosed = _ => _azukariyaSequence = -1;
                BoxWindow.OpenParam param = new BoxWindow.OpenParam();
                UIDatabase.SheetBoxOpenParam openData = UIManager.Instance.GetBoxOpenData(8);
                param.selectCount = openData.SelectCount - AzukariyaWork.GetStoredCount();
                int canBattlePokeCount = 0;
                for (uint i = 0; i < PlayerWork.playerParty.GetMemberCount(); i++)
                {
                    if (CheckCanBattlePokemonParam(PlayerWork.playerParty.GetMemberPointer(i)))
                        canBattlePokeCount++;
                }
                BoxScan(pokepara =>
                {
                    if (CheckCanBattlePokemonParam(pokepara))
                        canBattlePokeCount++;
                });
                if (canBattlePokeCount <= 3)
                    param.selectCount = 1;
                param.targetLevel = openData.Level;
                param.isEnableDying = openData.IsEnableDying;
                param.isEnableParty = openData.IsEnableParty;
                param.isEnableEgg = true;
                param.isShowSelectCount = true;
                param.isDisableDuplicate = true;
                boxWindow.Open(param, (window, selected) =>
                {
                    FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, selected.Length);
                    for (int i = 0; i < selected.Length; i++)
                    {
                        FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[i * 2 + 2].data, selected[i].IndexInTray);
                        FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[i * 2 + 3].data, selected[i].TrayIndex);
                    }
                }, UIWindow.WINDOWID_FIELD);
                _azukariyaSequence++;
            }
            return _azukariyaSequence < 0;
        }
		private bool EvCmdAzukariyaStore() {
            int temotiIndex1 = GetArgInt(_evArg[1]);
            int trayIndex1 = GetArgInt(_evArg[2]);
            int temotiIndex2 = GetArgInt(_evArg[3]);
            int trayIndex2 = GetArgInt(_evArg[4]);
            if (temotiIndex1 >= 0)
            {
                if (trayIndex1 >= 0)
                    AzukariyaWork.StoreFromBox(trayIndex1, temotiIndex1);
                else
                    AzukariyaWork.StoreFromTemoti(temotiIndex1);
            }
            if (temotiIndex2 >= 0)
            {
                if (trayIndex2 >= 0)
                {
                    AzukariyaWork.StoreFromBox(trayIndex2, temotiIndex2);
                }
                else
                {
                    // The party shrank when the first Pokemon came from it: shift the second index down (02c8caa4).
                    if (temotiIndex1 >= 0 && trayIndex1 < 0 && temotiIndex1 < temotiIndex2)
                        temotiIndex2--;
                    AzukariyaWork.StoreFromTemoti(temotiIndex2);
                }
            }
            return true;
        }
