		private bool EvCmd_CHANGE_FASHION_REQ() {
            switch (_fashionLoadSeq)
            {
                case 0:
                    {
                        _oldfashionAssetReqUri = "";
                        if (_fashionAssetReqOp != null)
                            _oldfashionAssetReqUri = _fashionAssetReqOp.assetBundleRequest.uri;
                        _fashionLoadSeq = 999;
                        CharacterDressData.SheetData[] dressData = DataManager.CharacterDressData.Data;
                        for (int i = 0; i < dressData.Length; i++)
                        {
                            CharacterDressData.SheetData data = dressData[i];
                            if (data.Index == PlayerWork.playerFashion)
                            {
                                _fashionAssetReqOp = AssetManager.AppendAssetBundleRequest("persons/field/" + data.FieldGraphic, true, null, null);
                                AssetManager.DispatchRequests(null);
                                _fashionLoadSeq = 1;
                                return false;
                            }
                        }
                    }
                    return false;
                case 1:
                    {
                        if (_fashionAssetReqOp.assetBundleRequest.status != RequestStatus.Complete)
                            return false;
                        FieldPlayerEntity oldPlayer = EntityManager.activeFieldPlayer;
                        _fashionYawAngle = oldPlayer.yawAngle;
                        _fashionWorldpos = oldPlayer.worldPosition;
                        UnityEngine.Object.Destroy(EntityManager.activeFieldPlayer.gameObject);
                        EntityManager.activeFieldPlayer = null;
                        UnityEngine.Object[] loadedAssets = _fashionAssetReqOp.assetBundleRequest.cache.loadedAssets;
                        for (int i = 0; i < loadedAssets.Length; i++)
                        {
                            if (loadedAssets[i] is GameObject prefab)
                            {
                                UnityEngine.Object.Instantiate<GameObject>(prefab, GameManager.fieldObjectHolder).GetComponent<BaseEntity>().Register();
                                break;
                            }
                        }
                        if (_oldfashionAssetReqUri != "")
                        {
                            AssetManager.UnloadAssetBundle(_oldfashionAssetReqUri);
                            _oldfashionAssetReqUri = "";
                        }
                        _fashionLoadSeq = 2;
                    }
                    return false;
                case 2:
                    {
                        FieldPlayerEntity player = EntityManager.activeFieldPlayer;
                        player.yawAngle = _fashionYawAngle;
                        player.worldPosition = _fashionWorldpos;
                        player.FashionTableID = PlayerWork.playerFashion;
                        player.WorkApplyVisibility();
                        ColorVariation colorVariation = player.GetComponent<ColorVariation>();
                        if (colorVariation != null)
                            colorVariation.ColorIndex = PlayerWork.colorID;
                        GameManager.fieldCamera.Target = EntityManager.activeFieldPlayer.transform;
                        int index = PlayerWork.playerSex ? 0 : 4;
                        player.SetAnimationEvents(DataManager.CharacterGraphics.Data[index].animTbl);
                        PlayReportManager.SaveReportLog_Custome();
                        _fashionLoadSeq = 0;
                    }
                    return true;
                default:
                    return false;
            }
        }
		private bool EvCmdWarpPanelStart() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            _fieldObjectRotateYaw.Update(_deltatime);
            switch (_warpSequence)
            {
                case 0:
                    {
                        float walkSpeed = DataManager.FieldCommonParam[(int)ParamIndx.WalkSpd].param;
                        player.PlayWalk();
                        _fieldObjectMove.SetObjectEntity(player);
                        FieldObjectEntity panel = _worpEventData.Entity ? (FieldObjectEntity)_worpEventData.Entity : player;
                        Vector3 targetPos = FieldObjectEntity.Vec2ToVec3Position(FieldObjectEntity.GridToPosition(panel.gridPosition), player.worldPosition.y);
                        _fieldObjectMove.MoveSpeed(targetPos, walkSpeed);
                        _fieldObjectRotateYaw.SetObjectEntity(player);
                        Vector3 dir = targetPos - player.worldPosition;
                        _fieldObjectRotateYaw.MoveTime((float)Math.Atan2(dir.x, dir.z) * Mathf.Rad2Deg, 0.1f);
                        _warpSequence++;
                    }
                    break;
                case 1:
                    {
                        if (_fieldObjectMove.IsBusy || _fieldObjectRotateYaw.IsBusy)
                            break;
                        GameManager.fieldCamera.IsUpdateStop = true;
                        player.PlaySpin(false);
                        player.isLanding = false;
                        _fieldObjectMove.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
                        Vector3 targetPos = player.worldPosition;
                        targetPos.y += DataManager.FieldCommonParam[(int)ParamIndx.WarpPanel_OfsY].param;
                        _fieldObjectMove.MoveTime(targetPos, DataManager.FieldCommonParam[(int)ParamIndx.WarpPanel_UpTime].param);
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI103, null);
                        _warpSequence++;
                    }
                    break;
                case 2:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    Fader.FadeOut();
                    _warpSequence++;
                    break;
                case 3:
                    if (Fader.isBusy)
                        break;
                    _warpSequence = -1;
                    break;
            }
            return _warpSequence < 0;
        }
		private bool EvCmdWarpPanelEnd() {
            FieldPlayerEntity player = EntityManager.activeFieldPlayer;
            _fieldObjectMove.Update(_deltatime);
            _fieldFloatMove.Update(_deltatime);
            switch (_warpSequence)
            {
                case 0:
                    {
                        GameManager.fieldCamera.IsUpdateStop = false;
                        GameManager.fieldCamera.ForceUpdateCamera();
                        GameManager.fieldCamera.IsUpdateStop = true;
                        player.PlaySpin(true);
                        player.isLanding = false;
                        _fieldObjectMove.SetObjectEntity(player);
                        _fieldObjectMove.FloatMove.EaseFunc = FieldFloatMove.EaseInOutSin;
                        Vector3 targetPos = player.worldPosition;
                        player.worldPosition.y += DataManager.FieldCommonParam[(int)ParamIndx.WarpPanel_OfsY].param;
                        _fieldObjectMove.MoveTime(targetPos, DataManager.FieldCommonParam[(int)ParamIndx.WarpPanel_DownTime].param);
                        Fader.FadeIn();
                        AudioManager.Instance.PlaySe(AK.EVENTS.S_FI104, null);
                        _warpSequence++;
                    }
                    break;
                case 1:
                    if (_fieldObjectMove.IsBusy)
                        break;
                    GameManager.fieldCamera.IsUpdateStop = false;
                    player.GetAnimationPlayer().SetAnimSpeed(0f);
                    player.PlayIdle();
                    _fieldFloatMove.SetValue(0f);
                    _fieldFloatMove.MoveTime(1f, 0.2f);
                    _warpSequence++;
                    break;
                case 2:
                    if (_fieldFloatMove.IsBusy)
                        break;
                    player.isLanding = true;
                    player.GetAnimationPlayer().ResetAnimSpeed();
                    _warpSequence = -1;
                    break;
            }
            return _warpSequence < 0;
        }
