		private bool CallWazaUiCommon(global::Dpr.UI.UIWazaManage.BootType bootType, global::Pml.PokePara.PokemonParam pokemonParam, global::System.Action<global::Pml.WazaNo, global::Pml.WazaNo> resultCallback, global::Pml.WazaNo oshieWazaNo = (global::Pml.WazaNo)(0)) {
            if (_pokelistSequence == 0)
            {
                UIWazaManage.Param param = new UIWazaManage.Param
                {
                    BootType = bootType,
                    IsOpenFromFieldScript = true,
                    PokemonParam = pokemonParam,
                    LearnWazaNo = oshieWazaNo,
                    ResultCallback = (learnWazaNo, unlearnWazaNo) =>
                    {
                        resultCallback.Invoke(learnWazaNo, unlearnWazaNo);
                        _pokelistSequence = -1;
                    },
                };
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UIManager>.Instance.CreateUIWindow<UIWazaManage>(UIWindowID.WAZA_MANAGE).Open(param);
                _pokelistSequence++;
            }
            return _pokelistSequence < 0;
        }
		private void LearnWaza(global::Pml.PokePara.PokemonParam param, global::Pml.WazaNo learnWazaNo, global::Pml.WazaNo unlearnWazaNo) {
            if (unlearnWazaNo != WazaNo.NULL)
                param.SetWaza(param.GetWazaIndex(unlearnWazaNo), learnWazaNo);
            else
                param.AddWazaIfEmptyExist(learnWazaNo);
        }
