		private bool EvCmd_CALL_EFFECT() {
            if (_effSeq == 2)
            {
                _effSeq = 0;
                return true;
            }
            if (_effSeq == 0)
            {
                // nested scope: the closure is created only here, as shipped
                int index;
                _effSeq = 1;
                index = GetArgInt(_evArg[1]);
                int effectId = GetArgInt(_evArg[2]);
                float x = GetArgFloat(_evArg[3]);
                float y = GetArgFloat(_evArg[4]);
                float z = GetArgFloat(_evArg[5]);
                FieldManager.Instance.CallEffect((EffectFieldID)effectId, new Vector3(x, y, z), eff =>
                {
                    _scriptEffects[index] = eff;
                    _effSeq = 2;
                }, eff => { });
            }
            return false;
        }
		private bool EvCmd_STOP_EFFECT() {
            int index = GetArgInt(_evArg[1]);
            int isForce = GetArgInt(_evArg[2]);
            Effect.EffectInstance effect = _scriptEffects[index];
            if (effect != null)
                effect.Stop(0f, isForce == 1);
            Coroutine coroutine = _scriptScaleCorutine[index];
            if (coroutine != null)
                Sequencer.Stop(coroutine);
            return true;
        }
		public bool EvCmd_RELEASE_EFFECT() {
            int index = GetArgInt(_evArg[1]);
            _scriptEffects[index] = null;
            Coroutine coroutine = _scriptScaleCorutine[index];
            if (coroutine != null)
                Sequencer.Stop(coroutine);
            _scriptScaleCorutine[index] = null;
            return true;
        }
		private bool EvCmd_CALL_EFFECT_OBJ() {
            if (_effSeq == 2)
            {
                _effSeq = 0;
                return true;
            }
            if (_effSeq == 0)
            {
                // nested scope: the closure is created only here, as shipped
                int index;
                _effSeq = 1;
                index = GetArgInt(_evArg[1]);
                int effectId = GetArgInt(_evArg[2]);
                int objIndex = GetArgInt(_evArg[3]);
                FieldObjectEntity entity = (objIndex >= 0 && objIndex < _fieldObjectEntity.Count) ? _fieldObjectEntity[objIndex] : null;
                FieldManager.Instance.CallEffect((EffectFieldID)effectId, entity.transform, eff =>
                {
                    _scriptEffects[index] = eff;
                    _effSeq = 2;
                }, eff => { });
            }
            return false;
        }
		private bool EvCmd_EFF_SCALE() {
            int index = GetArgInt(_evArg[1]);
            float min = GetArgFloat(_evArg[2]);
            float max = GetArgFloat(_evArg[3]);
            float spd = GetArgFloat(_evArg[4]);
            if (_scriptEffects[index] != null)
            {
                Coroutine coroutine = _scriptScaleCorutine[index];
                if (coroutine != null)
                    Sequencer.Stop(coroutine);
                _scriptScaleVectol[index] = true;
                _scriptScaleCorutine[index] = Sequencer.Start(EffScaleAnime(index, min, max, spd));
            }
            return true;
        }
		private global::System.Collections.IEnumerator EffScaleAnime(int index, float min, float max, float spd) {
            while (true)
            {
                float scale = _scriptEffects[index].gameObject.transform.localScale.x;
                if (_scriptScaleVectol[index])
                {
#if PC_UNLOCKED_FPS
                    scale += spd * PcPlatform.PcFrameClock.Frames;
#else
                    scale += spd;
#endif
                    if (scale >= max)
                    {
                        _scriptScaleVectol[index] = false;
                        scale = max;
                    }
                }
                else
                {
#if PC_UNLOCKED_FPS
                    scale -= spd * PcPlatform.PcFrameClock.Frames;
#else
                    scale -= spd;
#endif
                    if (scale <= min)
                    {
                        _scriptScaleVectol[index] = true;
                        scale = min;
                    }
                }
                _scriptEffects[index].gameObject.transform.localScale = new Vector3(scale, scale, scale);
                yield return null;
            }
        }
		private bool EvCmd_POKELIST_FORM_CHANGE_SET_PROC() {
            if (_pokelistSequence == 0)
            {
                int monsNo = GetArgInt(_evArg[1]);
                ushort formNo = (ushort)GetArgInt(_evArg[2]);
                _pokelistBox = -1;
                _pokelistIndex = -1;
                RotomSelectWindow window = UIManager.Instance.CreateUIWindow<RotomSelectWindow>(UIWindowID.ROTOM_SELECT);
                window.onClosed = _ => _pokelistSequence = -1;
                RotomSelectWindow.Param param = new RotomSelectWindow.Param();
                param.onSelected = index => _pokelistIndex = index;
                int count = (int)PlayerWork.playerParty.GetMemberCount();
                for (int i = 0; i < count; i++)
                {
                    PokemonParam pokemonParam = GetPokemonParam(-1, i);
                    param.selects.Add(!pokemonParam.IsEgg(EggCheckType.BOTH_EGG) && pokemonParam.GetMonsNo() == (MonsNo)monsNo && pokemonParam.GetFormNo() != formNo);
                }
                window.Open(param, UIWindow.WINDOWID_FIELD);
                _pokelistSequence++;
            }
            return _pokelistSequence < 0;
        }
