                {
                    UIZukanRegister window = UIManager.Instance.CreateUIWindow<UIZukanRegister>(UIWindowID.ZUKAN_REGISTER);
                    window.OnComplete += result =>
                    {
                        switch (result)
                        {
                            case UIZukanRegister.AddMemberResult.Party:
                                SetWork(resultIndex, 1);
                                break;
                            case UIZukanRegister.AddMemberResult.Box:
                                SetWork(resultIndex, 2);
                                break;
                            case UIZukanRegister.AddMemberResult.Cancel:
                                SetWork(resultIndex, 0);
                                break;
                        }
                        _azukariyaSequence = -1;
                    };
                    window.OpenAddMemberOnly(param, true);
                }
                _azukariyaSequence = 1;
            }
            return _azukariyaSequence < 0;
