		private bool EvCmd_POKETORE_START() {
            Vector2Int grid = EntityManager.activeFieldPlayer.gridPosition;
            float height = EntityManager.activeFieldPlayer.Height;
            if (!SwayGrass.SwayGrass_CheckValid() || !SwayGrass.SwayZone())
                SwayGrass.SwayGrass_InitSwayGrass();

            int result = SwayGrass.LotSwayGrass(ref grid, height);
            ENC_SV_DATA encData = PlayerWork.Enc_SV_Data;
            if (result == 1)
            {
                FieldManager.Instance.StopSwayGrass_NextArea();
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, 0);
                encData.PokeToreCharge = 0;
            }
            else if (result == 2)
            {
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, 1);
                encData.PokeToreCharge = 0;
            }
            else
            {
                FlagWork.SetWork((EvWork.WORK_INDEX)_evArg[1].data, 0);
            }
            PlayerWork.Enc_SV_Data = encData;
            return true;
        }
