        }
		private bool EvCmd_SET_LIGHTINTENSITY() {
            _isRunningLight[LIGHT_FILED] = true;
            _setlight_timer[LIGHT_FILED] = 0.0f;
            _start_lightIntensity[LIGHT_FILED] = EnvironmentController.global.AddLightIntensity;
            _setlight_timer_limit[LIGHT_FILED] = GetArgInt(_evArg[1]) / 30.0f;
            float light = GetArgFloat(_evArg[2]);
            if (light <= 0.0f)
                _end_lightIntensity[LIGHT_FILED] = 0.0f;
            else
                _end_lightIntensity[LIGHT_FILED] = light - EnvironmentController.global.parameters.LightIntensity;

            EnvironmentController.global.callback -= EnvironmentControllerSetLight;
            if (_setlight_timer_limit[LIGHT_FILED] <= 0.0f)
            {
                EnvironmentController.global.AddLightIntensity = _end_lightIntensity[LIGHT_FILED];
                _isRunningLight[LIGHT_FILED] = false;
            }
            else
            {
                EnvironmentController.global.callback += EnvironmentControllerSetLight;
            }
            return true;
        }
		private bool EvCmd_SET_LIGHTINTENSITY_CHARCTER() {
            _isRunningLight[LIGHT_CHAR] = true;
            _setlight_timer[LIGHT_CHAR] = 0.0f;
            _start_lightIntensity[LIGHT_CHAR] = EnvironmentController.global.AddCharacterLightIntensity;
            _setlight_timer_limit[LIGHT_CHAR] = GetArgInt(_evArg[1]) / 30.0f;
            float light = GetArgFloat(_evArg[2]);
            if (light <= 0.0f)
                _end_lightIntensity[LIGHT_CHAR] = 0.0f;
            else
                _end_lightIntensity[LIGHT_CHAR] = light - EnvironmentController.global.parameters.CharacterLightIntensity;

            EnvironmentController.global.callback -= EnvironmentControllerSetLightCharacter;
            if (_setlight_timer_limit[LIGHT_CHAR] <= 0.0f)
            {
                EnvironmentController.global.AddCharacterLightIntensity = _end_lightIntensity[LIGHT_CHAR];
                _isRunningLight[LIGHT_CHAR] = false;
            }
            else
            {
                EnvironmentController.global.callback += EnvironmentControllerSetLightCharacter;
            }
            return true;
        }
		private bool EvCmd_SET_LIGHTINTENSITY_POKE() {
            _isRunningLight[LIGHT_POKE] = true;
            _setlight_timer[LIGHT_POKE] = 0.0f;
            _start_lightIntensity[LIGHT_POKE] = EnvironmentController.global.AddPokeLightIntensity;
            _setlight_timer_limit[LIGHT_POKE] = GetArgInt(_evArg[1]) / 30.0f;
            float light = GetArgFloat(_evArg[2]);
            if (light <= 0.0f)
                _end_lightIntensity[LIGHT_POKE] = 0.0f;
            else
                _end_lightIntensity[LIGHT_POKE] = light - EnvironmentController.global.parameters.PokeLightIntensity;

            EnvironmentController.global.callback -= EnvironmentControllerSetLightPoke;
            if (_setlight_timer_limit[LIGHT_POKE] <= 0.0f)
            {
                EnvironmentController.global.AddPokeLightIntensity = _end_lightIntensity[LIGHT_POKE];
                _isRunningLight[LIGHT_POKE] = false;
            }
            else
            {
                EnvironmentController.global.callback += EnvironmentControllerSetLightPoke;
            }
            return true;
        }
		private void EnvironmentControllerSetLight(global::EnvironmentController controller, float deltaTime) {
            bool isEnd = EnviromentLightUpdate(LIGHT_FILED, deltaTime, out float light);
            controller.AddLightIntensity = light;
            if (isEnd)
            {
                EnvironmentController.global.callback -= EnvironmentControllerSetLight;
                _isRunningLight[LIGHT_FILED] = false;
            }
        }
		private void EnvironmentControllerSetLightCharacter(global::EnvironmentController controller, float deltaTime) {
            bool isEnd = EnviromentLightUpdate(LIGHT_CHAR, deltaTime, out float light);
            controller.AddCharacterLightIntensity = light;
            if (isEnd)
            {
                EnvironmentController.global.callback -= EnvironmentControllerSetLightCharacter;
                _isRunningLight[LIGHT_CHAR] = false;
            }
        }
		private void EnvironmentControllerSetLightPoke(global::EnvironmentController controller, float deltaTime) {
            bool isEnd = EnviromentLightUpdate(LIGHT_POKE, deltaTime, out float light);
            controller.AddPokeLightIntensity = light;
            if (isEnd)
            {
                EnvironmentController.global.callback -= EnvironmentControllerSetLightPoke;
                _isRunningLight[LIGHT_POKE] = false;
            }
        }
		private bool EnviromentLightUpdate(int index, float deltaTime, out float ret) {
            float t = _setlight_timer[index];
            if (t <= 0.0f)
                t = 0.0f;
            else
                t = t / _setlight_timer_limit[index];

            ret = Mathf.Lerp(_start_lightIntensity[index], _end_lightIntensity[index], t);
            if (t >= 1.0f)
            {
                ret = _end_lightIntensity[index];
                return true;
            }
            _setlight_timer[index] += deltaTime;
            return false;
        }
