		private bool EvCmd_USE_SPECIAL_ITEM() {
            if (_itemSequence == 0)
            {
                int itemNo = GetArgInt(_evArg[1]);
                _itemSequence = 1;
                switch ((ItemNo)itemNo)
                {
                    case ItemNo.POFINKEESU:
                        {
                            UIPofinCase window = UIManager.Instance.CreateUIWindow<UIPofinCase>(UIWindowID.POFIN_CASE);
                            window.onClosed += _ => _itemSequence = -1;
                            window.Open(UIWindow.WINDOWID_FIELD);
                        }
                        break;
                    case ItemNo.BOUKENNOOTO:
                        {
                            AdventureNoteWindow window = UIManager.Instance.CreateUIWindow<AdventureNoteWindow>(UIWindowID.ADVENTURE_NOTE);
                            window.onClosed += _ => _itemSequence = -1;
                            window.Open(UIWindow.WINDOWID_FIELD);
                        }
                        break;
                    case ItemNo.DSPLAYER:
                        UIManager.Instance.UseDSPlayerItem();
                        _itemSequence = -1;
                        break;
                }
            }
            return _itemSequence < 0;
        }
