		private bool EvCmd_BTWR_SUB_SELECT_POKE() {
            switch (_btwrSequence)
            {
                case 0:
                    {
                        BtlTowerWork.GetNowModeEnum(out TowerLotRule rule, out TowerLotCls cls);
                        BattleMatchingWork.SetBattleTowerRule(rule != TowerLotRule.Double);
                        Sequencer.Start(BattleMatchingManager.LoadBattleTowerUI(() =>
                        {
                            BattleMatchingWork.pokemonParams = null;
                            BattleMatchingWork.battleTeamIndex = -1;
                            UIManager.Instance.CreateUIWindow<UIBattleMatchingTeamSelect>(UIWindowID.BATTLE_MATCHING_TEAM_SELECT).Open(() => _btwrSequence = 4, () => _btwrSequence = 6, true, true, true, UIWindow.WINDOWID_FIELD);
                            _btwrSequence = 3;
                        }));
                    }
                    break;
                case 2:
                    BattleMatchingWork.pokemonParams = null;
                    BattleMatchingWork.battleTeamIndex = -1;
                    UIManager.Instance.CreateUIWindow<UIBattleMatchingTeamSelect>(UIWindowID.BATTLE_MATCHING_TEAM_SELECT).Open(() => _btwrSequence = 4, () => _btwrSequence = 6, false, false, true, UIWindow.WINDOWID_FIELD);
                    break;
                case 4:
                    UIManager.Instance.CreateUIWindow<UIBattleMatchingPokemonSelect>(UIWindowID.BATTLE_MATCHING_POKE_SELECT).Open(() => _btwrSequence = 6, () => _btwrSequence = 2, true, true, UIWindow.WINDOWID_FIELD);
                    break;
                case 6:
                    _btwrSequence = 0;
                    BattleMatchingManager.UnloadBattleTowerUI();
                    return true;
                default:
                    return false;
            }
            _btwrSequence++;
            return false;
        }
