		private bool EvCmd_OPEN_BATTLE_WIN() {
            switch (_talkStart)
            {
                case TalkState.Init:
                    {
                        _talkStart = TalkState.EndWait;
                        Sequencer.Start(LoadBattleWindow(OpenBattleWindow));
                        MsgWindowParam param = new MsgWindowParam();
                        param.labelName = UnionTextData.UNION_BATTLE_RULE;
                        param.useMsgFile = MessageManager.Instance.GetMsgFile("ss_net_net_btl");
                        param.inputEnabled = false;
                        param.wndAnchorPos = UnionTextData.BATTLE_RULE_ANCHOR_POS;
                        MsgWindowManager.OpenMsg(param);
                    }
                    return false;
                case TalkState.CloseWait:
                    ResetSelectMsgWindowStringDate();
                    _msgWindow.CloseWindow();
                    _talkStart = TalkState.Init;
                    return true;
                default:
                    return false;
            }
        }
		private global::System.Collections.IEnumerator LoadBattleWindow(global::System.Action onLoad) {
            yield return UIManager.Instance.OpLoadWindows(new List<UIWindowID> { UIWindowID.BATTLE_RULE_SELECT }, true);
            onLoad?.Invoke();
        }
		private void OpenBattleWindow() {
            void OnSelectChoices(int i)
            {
                FlagWork.SetWork((EvWork.WORK_INDEX)_evCommand.Arg[1].data, i);
                _talkStart = TalkState.CloseWait;
            }

            List<Dpr.NetworkUtils.BattleModeID> battleModes = new List<Dpr.NetworkUtils.BattleModeID>();
            battleModes.Add(Dpr.NetworkUtils.BattleModeID.Single);
            battleModes.Add(Dpr.NetworkUtils.BattleModeID.Double);
            battleModes.Add(Dpr.NetworkUtils.BattleModeID.Multi);
            UIManager.Instance.CreateUIWindow<BattleRuleSelectWindow>(UIWindowID.BATTLE_RULE_SELECT).Open(battleModes, mode =>
            {
                int index;
                switch (mode)
                {
                    case Dpr.NetworkUtils.BattleModeID.Single:
                        index = 0;
                        break;
                    case Dpr.NetworkUtils.BattleModeID.Double:
                        index = 1;
                        break;
                    case Dpr.NetworkUtils.BattleModeID.Mix:
                        index = 3;
                        break;
                    case Dpr.NetworkUtils.BattleModeID.Multi:
                        index = 2;
                        break;
                    default:
                        index = 3;
                        break;
                }
                OnSelectChoices(index);
            }, () => OnSelectChoices(3), true, UIWindow.WINDOWID_FIELD);
        }
		private bool EvCmd_OJIGI() {
            FieldObjectEntity objectEntity;
            if (_evArg[1].argType == EvData.ArgType.String)
                objectEntity = Find_fieldObjectEntity(GetArgString(_evData, _evArg[1]));
            else
                objectEntity = GetFieldObject(GetArgInt(_evArg[1]));

            FieldCharacterEntity entity = (FieldCharacterEntity)objectEntity;
            if (entity == null)
                return true;

            if (entity.GetAnimationPlayer().currentIndex == 16)
                return true;

            entity.GetAnimationPlayer().Play(16, 0.0f, 0.0f);
            entity.SetAnimeEndCallBack(OjibiCallback);
            return true;
        }
		private bool OjibiCallback(global::AnimationPlayer anime) {
            if (anime.currentIndex == 16)
                anime.Play(0, 0.2f, 0.0f);

            return true;
        }
