            switch ((EvCmdID.NAME)index)
            {
                case EvCmdID.NAME._NOP: return EvCmdNop();
                case EvCmdID.NAME._DUMMY: return EvCmdDummy();
                case EvCmdID.NAME._END: return EvCmdEnd();
                case EvCmdID.NAME._TIME_WAIT: return EvCmdTimeWait();
