		private bool WarpSegmentHitCheck(global::FieldEventDoorEntity entity, out global::UnityEngine.Vector3 reusltPosition, out float subtendedAngle, out float lineDistance, float hitrange) {
            reusltPosition = Vector3.zero;
            subtendedAngle = 0.0f;
            lineDistance = 0.0f;
            float x = entity.worldPosition.x;
            float z = entity.worldPosition.z;
            Vector2 offset = entity.offset;
            Vector2 size = entity.size;
            Vector2 segA = Vector2.zero;
            Vector2 segB = Vector2.zero;
            Vector2 targetPos = new Vector2(EntityManager.activeFieldPlayer.worldPosition.x, EntityManager.activeFieldPlayer.worldPosition.z);
            x = x - offset.x;
            z = z + offset.y;
            Vector2 forward = new Vector2(EntityManager.activeFieldPlayer.transform.forward.x, EntityManager.activeFieldPlayer.transform.forward.z);
            float angleAT;
            float angleBT;
            float distance;
            int hitstatus;
            switch (entity.startVectol)
            {
                case FieldDoor.StartVectol.Up:
                    segA = new Vector2(x, z);
                    segB = new Vector2(x - size.x, z);
                    break;
                case FieldDoor.StartVectol.Down:
                    segA = new Vector2(x, z - size.y);
                    segB = new Vector2(x - size.x, z - size.y);
                    break;
                case FieldDoor.StartVectol.Left:
                    segA = new Vector2(x - size.x, z);
                    segB = new Vector2(x - size.x, z - size.y);
                    break;
                case FieldDoor.StartVectol.Right:
                    segA = new Vector2(x, z);
                    segB = new Vector2(x, z - size.y);
                    break;
            }
            if (entity.startVectol != FieldDoor.StartVectol.All)
            {
                SegmentHit(ref segA, ref segB, ref targetPos, hitrange, out angleAT, out angleBT, out distance, out hitstatus);
                if (hitstatus == 0 || angleAT > 90.0f || angleBT > 90.0f)
                    return false;
            }

            float radius = size.x * size.y + 0.1f;
            float halfX = size.x < 1.0f ? size.x * 0.5f : 0.5f;
            float halfZ = size.y < 1.0f ? size.y * 0.5f : 0.5f;
            segA = new Vector2(x - halfX, z - halfZ);
            segB = new Vector2((x - size.x) + halfX, (z - size.y) + halfZ);
            SegmentHit(ref segA, ref segB, ref targetPos, radius, out angleAT, out angleBT, out distance, out hitstatus);
            Vector2 dir = (segB - segA).normalized;
            Vector2 normal = new Vector2(-dir.y, dir.x);
            Vector2 hitPos = Vector2.zero;
            if (hitstatus == 3)
                hitPos = segB;
            else if (hitstatus == 2)
                hitPos = segA;
            else if (hitstatus == 1)
                hitPos = targetPos - normal * distance;

            Vector2 toHit = hitPos - targetPos;
            subtendedAngle = FieldCalc.SubtendedAngle(ref toHit, ref forward);
            reusltPosition = new Vector3(hitPos.x, entity.Height, hitPos.y);
            lineDistance = distance;
            return hitstatus != 0;
        }
		private void SegmentHit(ref global::UnityEngine.Vector2 segA, ref global::UnityEngine.Vector2 segB, ref global::UnityEngine.Vector2 targetPos, float radius, out float angleAT, out float angleBT, out float distance, out int hitstatus) {
            hitstatus = 0;
            Vector2 ab = (segB - segA).normalized;
            Vector2 at = targetPos - segA;
            Vector2 bt = targetPos - segB;
            float dotA = Vector2.Dot(ab, at.normalized);
            float dotB = Vector2.Dot(ab, bt.normalized);
            angleAT = Mathf.Acos(dotA) * Mathf.Rad2Deg;
            angleBT = Mathf.Acos(-dotB) * Mathf.Rad2Deg;
            distance = FieldCalc.Cross(ref ab, ref at);
            if (dotA <= 0.0f || ab == Vector2.zero)
            {
                if (at.sqrMagnitude < radius * radius)
                    hitstatus = 2;
            }
            else if (dotB >= 0.0f)
            {
                if (bt.sqrMagnitude < radius * radius)
                    hitstatus = 3;
            }
            else
            {
                if (Mathf.Abs(distance) < radius)
                    hitstatus = 1;
            }
        }
		public void InitScriptLoad() {
            MessageManager.Instance.Initialize(MessageEnumData.MsgLangId.JPN);
            _scriptOperation = AssetManager.AppendAssetBundleRequest("ev_script", true, null, null);
            AssetManager.DispatchRequests(null);
        }
		public bool InitScriptLoadWait() {
            if (_scriptOperation != null)
            {
                if (_scriptOperation.assetBundleRequest.status != RequestStatus.Complete)
                    return false;

                int length = _scriptOperation.assetBundleRequest.cache.loadedAssets.Length;
                _eventList = new EvScriptData[length];
                for (int i = 0; i < length; i++)
                {
                    UnityEngine.Object asset = _scriptOperation.assetBundleRequest.cache.loadedAssets[i];
                    if (asset is EvData ev)
                    {
                        if (ev == null)
                            continue;
                        _eventList[i] = new EvScriptData(ev);
                    }
                    else if (asset is EventCameraTable cameraTable)
                    {
                        _evCameraTable = cameraTable;
                    }
                }
                AssetManager.UnloadAssetBundle(_scriptOperation.assetBundleRequest.uri);
                _scriptOperation = null;
            }
            return true;
        }
		public void InitScriptEnd() {
            if (!_isScriptLoad)
                return;

            for (int i = 0; i < _eventList.Length; i++)
            {
                EvScriptData scriptData = _eventList[i];
                if (scriptData == null)
                    continue;

                for (int j = 0; j < scriptData.EvData.Scripts.Count; j++)
                {
                    int[] index = new int[] { i, j };
                    EvData.Script script = scriptData.EvData.Scripts[j];
                    if (!_findAllLabel.ContainsKey(script.Label))
                        _findAllLabel.Add(script.Label, index);
                }
            }
        }
		private bool IsRockclimbLabel(string label) {
            return label == "ev_hiden_kabenobori";
        }
		public void SaveDataReflection() {
            EntityManager.BuildFieldEntities();
            foreach (FieldObjectEntity entity in _fieldObjectEntity)
            {
                if (entity == null || entity.gameObject == null)
                    continue;

                FIELD_OBJ_SAVE_DATA data = FieldObjWork.Get(entity.gameObject.name.GetHashCode(), out bool flag);
                if (!flag)
                    continue;

                entity.gridPosition = new Vector2Int(data.grid_x, data.grid_y);
                entity.worldPosition.y = data.height;
                entity.yawAngle = data.angle;
                int moveCodeIndex = entity.EventParams.MoveCodeIndex;
                if (moveCodeIndex >= 0)
                {
                    FieldObjectMoveCode moveCode = FieldObjectMoveCodes[moveCodeIndex];
                    moveCode.MoveCode = data.movecode;
                    moveCode.MoveDirHead = (DIR)data.dir_head;
                    moveCode.MoveParam0 = data.mvParam0;
                    moveCode.MoveParam1 = data.mvParam1;
                    moveCode.MoveParam2 = data.mvParam2;
                    moveCode.MoveLimitX = data.limitX;
                    moveCode.MoveLimitZ = data.limitZ;
                    moveCode.Ev_Type = data.ev_type;
                    moveCode.mv_old_dir = data.mv_old_dir;
                    moveCode.mv_dir = data.mv_dir;
                }
            }

            for (int i = 0; i < EntityManager.fieldTobariGymWalls.Length; i++)
            {
                FieldTobariGymWallEntity wall = EntityManager.fieldTobariGymWalls[i];
                if (wall == null || wall.gameObject == null)
                    continue;

                FIELD_OBJ_SAVE_DATA data = FieldObjWork.Get(wall.name.GetHashCode(), out bool flag);
                if (flag)
                    wall.ApplySaveData(in data);
            }

            if (EntityManager.fieldNomoseGymWater.Length != 0)
            {
                FieldNomoseGymWaterEntity water = EntityManager.fieldNomoseGymWater[0];
                if (water != null && water.gameObject != null)
                {
                    FIELD_OBJ_SAVE_DATA data = FieldObjWork.Get(water.name.GetHashCode(), out bool flag);
                    if (flag)
                        water.ApplySaveData(in data);
                }
            }
        }
		public void SetSaveObj() {
            foreach (var entity in _fieldObjectEntity)
            {
                if (entity == null)
                    continue;

                if (entity.gameObject == null)
                    continue;

                if (!entity.EventParams.SaveObject)
                    continue;

                var data = new FIELD_OBJ_SAVE_DATA();
                data.name_hash = entity.gameObject.name.GetHashCode();
                data.active = entity.gameObject.activeInHierarchy;
                var grid = FieldObjectEntity.PositionToGrid(entity.worldPosition);
                data.grid_x = grid.x;
                data.grid_y = grid.y;
                data.height = (int)(entity.worldPosition.y + 0.5f);
                data.angle = (int)entity.yawAngle;

                int moveCodeIndex = entity.EventParams.MoveCodeIndex;
                if (moveCodeIndex >= 0)
                {
                    var moveCode = FieldObjectMoveCodes[moveCodeIndex];
                    data.movecode = moveCode.MoveCode;
                    data.dir_head = (int)moveCode.MoveDirHead;
                    data.mvParam0 = moveCode.MoveParam0;
                    data.mvParam1 = moveCode.MoveParam1;
                    data.mvParam2 = moveCode.MoveParam2;
                    data.limitX = moveCode.MoveLimitX;
                    data.limitZ = moveCode.MoveLimitZ;
                    data.ev_type = moveCode.Ev_Type;
                    data.mv_old_dir = moveCode.mv_old_dir;
                    data.mv_dir = moveCode.mv_dir;
                }

                FieldObjWork.Set(data);
            }

            foreach (var wall in EntityManager.fieldTobariGymWalls)
            {
                if (wall == null)
                    continue;

                if (wall.gameObject == null)
                    continue;

                var data = new FIELD_OBJ_SAVE_DATA();
                data.name_hash = wall.name.GetHashCode();
                wall.CreateSaveData(ref data);
                FieldObjWork.Set(data);
            }

            if (EntityManager.fieldNomoseGymWater.Length != 0)
            {
                var water = EntityManager.fieldNomoseGymWater[0];
                if (water != null && water.gameObject != null)
                {
                    var data = new FIELD_OBJ_SAVE_DATA();
                    data.name_hash = water.name.GetHashCode();
                    water.CreateSaveData(ref data);
                    FieldObjWork.Set(data);
                }
            }
        }
		public void SetupGimmickEntity() {
            EntityManager.BuildFieldEntities();
            for (int i = 0; i < EntityManager.fieldTobariGymWalls.Length; i++)
            {
                FieldTobariGymWallEntity wall = EntityManager.fieldTobariGymWalls[i];
                if (wall == null || wall.gameObject == null)
                    continue;
                wall.Setup();
            }

            if (EntityManager.fieldNagisaGymGears != null && EntityManager.fieldNagisaGymGears.Length != 0)
            {
                for (int i = 0; i < EntityManager.fieldNagisaGymGears.Length; i++)
                {
                    FieldNagisaGymGearEntity gear = EntityManager.fieldNagisaGymGears[i];
                    if (gear == null || gear.gameObject == null)
                        continue;
                    gear.Setup(_areaID);
                }
            }
            else
            {
                GimmickWork.ClearGearRotate();
            }

            for (int i = 0; i < EntityManager.fieldLiftObjects.Length; i++)
            {
                FieldEventLiftEntity lift = EntityManager.fieldLiftObjects[i];
                if (lift == null || lift.gameObject == null)
                    continue;
                lift.Setup();
            }

            if (EntityManager.fieldNomoseGymWater.Length != 0)
            {
                FieldNomoseGymWaterEntity water = EntityManager.fieldNomoseGymWater[0];
                if (water != null && water.gameObject != null)
                    water.Setup();
            }

            for (int i = 0; i < EntityManager.fieldNomoseGymSwitches.Length; i++)
            {
                FieldNomoseGymSwitchEntity sw = EntityManager.fieldNomoseGymSwitches[i];
                if (sw == null || sw.gameObject == null)
                    continue;
                sw.Setup();
            }

            if (EntityManager.fieldElevatorBackground.Length != 0)
            {
                FieldElevatorBackgroundEntity elevator = EntityManager.fieldElevatorBackground[0];
                if (elevator != null && elevator.gameObject != null)
                    elevator.Setup();
            }
        }
		public void SceneStartGimmickEntity() {
            if (EntityManager.fieldNagisaGymGears == null)
                return;
            if (EntityManager.fieldNagisaGymGears.Length == 0)
                return;

            for (int i = 0; i < EntityManager.fieldNagisaGymGears.Length; i++)
            {
                FieldNagisaGymGearEntity gear = EntityManager.fieldNagisaGymGears[i];
                if (gear == null || gear.gameObject == null)
                    continue;
                gear.SceneStart();
            }
        }
		public static void PlayHoneyTreeAnimation(global::ZoneID zoneId) {
            var honeyData = HoneyWork.GetHoneyData(zoneId);
            if (!honeyData.HasValue)
                return;

            var entity = Array.Find(EntityManager.fieldEventObjects, e => e.EventParams.HoneyTree && e.EventParams.LocaitionZoneID == zoneId);
            if (entity != null)
            {
                int index = 0;
                uint state = AK.SWITCHES.SWEETTREE.SWITCH.TREE_STOP;
                if (HoneyWork.CalcState(honeyData.Value) == HoneyWork.State.HONEY_SPREAD_ENCOUNT)
                {
                    // index = SwayLv + 1, state from the rodata table @03ddb5bc {TREE_S, TREE_M, TREE_L}.
                    switch (honeyData.Value.SwayLv)
                    {
                        case 0:
                            index = 1;
                            state = AK.SWITCHES.SWEETTREE.SWITCH.TREE_S;
                            break;
                        case 1:
                            index = 2;
                            state = AK.SWITCHES.SWEETTREE.SWITCH.TREE_M;
                            break;
                        case 2:
                            index = 3;
                            state = AK.SWITCHES.SWEETTREE.SWITCH.TREE_L;
                            break;
                    }
                }

                entity.Play(index);
                var ambient = entity.GetComponentInChildren<AudioAmbient>();
                if (ambient != null)
                    ambient.SetSwitch(AK.SWITCHES.SWEETTREE.GROUP, state);
            }
        }
		private void CreateWorpPoint() {
            if (_warpRoot == null)
            {
                _warpRoot = new UnityEngine.GameObject();
                _warpRoot.name = "WarpObjectRoot";
            }
            UnityEngine.Transform root = _warpRoot.transform;
            int childCount = root.childCount;
            for (int i = 0; i < childCount; i++)
                UnityEngine.Object.Destroy(root.GetChild(i).gameObject);
            _warpList.Clear();
            _warpData = null;
            string key = string.Format("MapWarp_{0}", _areaID);
            if (!DataManager.MapWarpData.ContainsKey(key))
                return;
            _warpData = DataManager.MapWarpData[key];
            var groups = new System.Collections.Generic.Dictionary<int, System.Collections.Generic.List<CreateWarp>>(50);
            for (int i = 0; i < _warpData.Data.Length; i++)
            {
                var cw = new CreateWarp();
                cw.data = _warpData.Data[i];
                cw.index = i;
                int groupId = cw.data.GruopID;
                if (groups.ContainsKey(groupId))
                {
                    groups[groupId].Add(cw);
                }
                else
                {
                    var list = new System.Collections.Generic.List<CreateWarp>(30);
                    list.Add(cw);
                    groups.Add(groupId, list);
                }
            }
            foreach (var kv in groups)
            {
                var list = kv.Value;
                if (kv.Key == -1 || kv.Key == 0)
                {
                    foreach (var cw in list)
                    {
                        var data = cw.data;
                        int[] index = new int[1];
                        index[0] = cw.index;
                        UnityEngine.Vector2 size = data.Size;
                        int[] locator = new int[1];
                        locator[0] = data.WarpIndex;
                        _warpList.Add(CreateWarpEntity(data, index, size, locator));
                    }
                }
                else
                {
                    var first = list[0].data;
                    UnityEngine.Vector2 size = first.Size;
                    UnityEngine.Vector2 pos = new UnityEngine.Vector2(first.Position.x, first.Position.z);
                    int[] locator = new int[list.Count];
                    locator[0] = first.WarpIndex;
                    int[] index = new int[list.Count];
                    index[0] = list[0].index;
                    for (int i = 1; i < list.Count; i++)
                    {
                        var data = list[i].data;
                        locator[i] = data.WarpIndex;
                        index[i] = list[i].index;
                        size.x += data.Position.x - pos.x;
                        size.y += data.Position.z - pos.y;
                        pos.x = data.Position.x;
                        pos.y = data.Position.z;
                    }
                    _warpList.Add(CreateWarpEntity(first, index, size, locator));
                }
            }
        }
		private global::FieldEventDoorEntity CreateWarpEntity(global::XLSXContent.MapWarp.SheetData data, int[] index, global::UnityEngine.Vector2 size, int[] locator) {
            UnityEngine.Vector3 position = new UnityEngine.Vector3(-data.Position.x, data.Position.y, data.Position.z);
            UnityEngine.GameObject go = new UnityEngine.GameObject();
            go.name = string.Format("{0}_W{1:D2}", _areaID, index[0]);
            global::FieldEventDoorEntity entity = go.AddComponent<global::FieldEventDoorEntity>();
            entity.transform.SetParent(_warpRoot.transform);
            entity.transform.localPosition = position;
            entity.EventParams.IsContact = false;
            entity.mdIndexArray = index;
            entity.EventParams.Type = EntityType.Warp;
            entity.entityEname = go.name;
            float sx = size.x > 0f ? size.x : 1f;
            float sy = size.y > 0f ? size.y : 1f;
            entity.size.x = sx;
            entity.shapeType = global::FieldEventEntity.ShapeType.Box;
            entity.size.y = sy;
            entity.offset.x = sx < 1f ? sx * -0.5f : -0.5f;
            entity.offset.y = sy < 1f ? sy * 0.5f : sy + -0.5f;
            switch (data.InputDir)
            {
                case 0: entity.startVectol = global::FieldDoor.StartVectol.Up; break;
                case 1: entity.startVectol = global::FieldDoor.StartVectol.Left; break;
                case 2: entity.startVectol = global::FieldDoor.StartVectol.Down; break;
                case 3: entity.startVectol = global::FieldDoor.StartVectol.Right; break;
                case 4: entity.startVectol = global::FieldDoor.StartVectol.All; break;
            }
            entity.transitionZone = data.WarpZone;
            entity.locatorIndex = data.WarpIndex;
            entity.locatorArray = locator;
            entity.callLabel = data.ScriptLabel;
            entity.exitLabel = data.ExitLabel;
            entity.connectionName = data.ConnectionName;
            switch (entity.startVectol)
            {
                case global::FieldDoor.StartVectol.Up: entity.offset.y += -1f; break;
                case global::FieldDoor.StartVectol.Down: entity.offset.y += 1f; break;
                case global::FieldDoor.StartVectol.Left: entity.offset.x += -1f; break;
                case global::FieldDoor.StartVectol.Right: entity.offset.x += 1f; break;
            }
            return entity;
        }
		public global::System.Collections.IEnumerator RequestAssetSetUp(global::AreaID areaid) {
            while (!DataManager.IsLoaded())
                yield return null;
            if (_isScriptLoad)
            {
                InitScriptLoad();
                while (!InitScriptLoadWait())
                    yield return null;
                InitScriptEnd();
            }
            if (PlayerWork.Warp == PlayerWork.WarpType.None && areaid == _areaID && !GameManager.mapInfo[(int)PlayerWork.transitionZoneID].Reload)
                yield break;
            _areaID = areaid;
            if (areaid == global::AreaID.UNKNOWN)
                yield break;
            if (FieldObjectMoveCodes == null)
                FieldObjectMoveCodes = new System.Collections.Generic.List<global::FieldObjectMoveCode>(200);
            FieldObjectMoveCodes.Clear();
            _fieldObjectEntity.Clear();
            _FieldKinomiGrowEntity.Clear();
            _loadObjectList.Clear();
            _loadObjectIndex = 0;
            _AssetReqOpeList.RemoveAll(val => val == null);
            for (int i = 0; i < _AssetReqOpeList.Count; i++)
                _AssetReqOpeList[i].RefCount = 0;
            string key = "PlaceData_" + _areaID.ToString();
            if (!DataManager.PlaceData.ContainsKey(key))
                yield break;
            global::XLSXContent.PlaceData placeData = DataManager.PlaceData[key];
            if (placeData.Data.Length > 0)
            {
                int graphicsCount = DataManager.CharacterGraphics.Data.Length;
                for (int i = 0; i < placeData.Data.Length; i++)
                {
                    global::XLSXContent.PlaceData.SheetData pd = placeData.Data[i];
                    if (pd == null)
                        continue;
                    if (pd.DoNotLoad != EvWork.FLAG_INDEX.FLAG_END_SAVE_SIZE && FlagWork.GetFlag(pd.DoNotLoad))
                        continue;
                    LoadObjectData lod = new LoadObjectData();
                    lod.IsLoadFast = pd.LoadFirst;
                    lod.ObjectName = pd.ID;
                    lod.PlaceData = placeData.Data[i];
                    lod.Position = pd.Position;
                    lod.Height = pd.HeightLayer;
                    lod.IsCreated = false;
                    lod.Angle = pd.Rotation;
                    lod.MoveCode = pd.MoveCode;
                    lod.MoveDirHead = global::FieldObjectEntity.GetDir(pd.Rotation);
                    lod.MoveParam0 = pd.MoveParam0;
                    lod.MoveParam1 = pd.MoveParam1;
                    lod.MoveParam2 = pd.MoveParam2;
                    lod.MoveLimitX = (int)pd.MoveLimit.x;
                    lod.MoveLimitZ = (int)pd.MoveLimit.y;
                    lod.Ev_Type = pd.EventType;
                    lod.mv_old_dir = (int)lod.MoveDirHead;
                    lod.mv_dir = (int)lod.MoveDirHead;
                    SetSaveDataParam(ref lod);
                    int graphic = pd.ObjectGraphicIndex;
                    if (_areaID == global::AreaID.D31R0205 || _areaID == global::AreaID.D31R0206)
                    {
                        int mode = BtlTowerWork.GetMode();
                        int rank = BtlTowerWork.GetRank(mode);
                        int trainerIndex = 0;
                        int round = 0;
                        if (pd.ID == "TOWER_PLAYER_01_01") { trainerIndex = 0; round = 1; }
                        else if (pd.ID == "TOWER_PLAYER_02_01") { trainerIndex = 0; round = 2; }
                        else if (pd.ID == "TOWER_PLAYER_03_01") { trainerIndex = 0; round = 3; }
                        else if (pd.ID == "TOWER_PLAYER_04_01") { trainerIndex = 0; round = 4; }
                        else if (pd.ID == "TOWER_PLAYER_05_01") { trainerIndex = 0; round = 5; }
                        else if (pd.ID == "TOWER_PLAYER_06_01") { trainerIndex = 0; round = 6; }
                        else if (pd.ID == "TOWER_PLAYER_07_01") { trainerIndex = 0; round = 7; }
                        else if (mode == 3)
                        {
                            if (pd.ID == "TOWER_PLAYER_01_02") { trainerIndex = 1; round = 1; }
                            else if (pd.ID == "TOWER_PLAYER_02_02") { trainerIndex = 1; round = 2; }
                            else if (pd.ID == "TOWER_PLAYER_03_02") { trainerIndex = 1; round = 3; }
                            else if (pd.ID == "TOWER_PLAYER_04_02") { trainerIndex = 1; round = 4; }
                            else if (pd.ID == "TOWER_PLAYER_05_02") { trainerIndex = 1; round = 5; }
                            else if (pd.ID == "TOWER_PLAYER_06_02") { trainerIndex = 1; round = 6; }
                            else if (pd.ID == "TOWER_PLAYER_07_02") { trainerIndex = 1; round = 7; }
                        }
                        if (round != 0)
                        {
                            BtlTowerWork.GetNowModeEnum(out global::TowerLotRule lotRule, out global::TowerLotCls lotCls);
                            ulong seed = BtlTowerWork.GetTrainerRand(round - 1);
                            graphic = TrainerSystem.CreateTowerLotResult(lotRule, lotCls, rank, round, seed).GetTrainerData(trainerIndex).fldGraphic;
                            lod.replaceGraphicIndex = graphic;
                        }
                    }
                    if (graphic < 0)
                    {
                        lod.AssetReqIndex = -1;
                    }
                    else
                    {
                        string path = "";
                        if (graphic == 4)
                            graphic = PlayerWork.playerSex ? 140 : 139;
                        if (graphic >= Graphic_Poke)
                        {
                            path = string.Format("{0}pm{1:D4}_{2:D2}_{3:D2}", Path_Poke_Model, graphic / 10000, graphic / 100 % 100, graphic % 100);
                        }
                        else if (graphic >= Graphic_Gimmick && graphic < Graphic_Gimmick + 500)
                        {
                            path = DataManager.GimmickGraphics.Data[graphic - Graphic_Gimmick].AssetPath;
                        }
                        else if (graphic >= Graphic_SekiZou && graphic < Graphic_SekiZouMAX)
                        {
                            path = string.Format("pokemons/statue/{0}", graphic - Graphic_SekiZou);
                        }
                        else if (graphic >= 0 && graphic < graphicsCount)
                        {
                            path = Path_Parsons + DataManager.CharacterGraphics.Data[graphic].FieldGraphic;
                        }
                        if (string.IsNullOrEmpty(path))
                            continue;
                        int reqIndex = -1;
                        for (int j = 0; j < _AssetReqOpeList.Count; j++)
                        {
                            if (_AssetReqOpeList[j].ReqOpe.assetBundleRequest.uri == path)
                            {
                                _AssetReqOpeList[j].RefCount = 1;
                                reqIndex = j;
                                break;
                            }
                        }
                        if (reqIndex < 0)
                        {
                            AssetReqOpeRef reqOpe = new AssetReqOpeRef();
                            reqOpe.RefCount = 1;
                            reqOpe.ReqOpe = AssetManager.AppendAssetBundleRequest(path, true, null, null);
                            _AssetReqOpeList.Add(reqOpe);
                            reqIndex = _AssetReqOpeList.Count - 1;
                        }
                        lod.AssetReqIndex = reqIndex;
                    }
                    _loadObjectList.Add(lod);
                }
            }
            string log = "fieldasset request \n";
            for (int i = 0; i < _AssetReqOpeList.Count; i++)
            {
                if (_AssetReqOpeList[i] != null)
                    log += string.Format("[{0}]{1}  [{2}]\n", i, _AssetReqOpeList[i].isEnd, _AssetReqOpeList[i].ReqOpe.assetBundleRequest.uri);
            }
            AssetManager.DispatchRequests(null);
        }
